"""Shared policy for labels retained in an ingredient's synonym history."""

from __future__ import annotations

import re
from collections.abc import Mapping
from typing import Any

# These entries preserve a rejected candidate and its provenance in curated
# YAML.  They are not names the record answers to and must not be exposed by
# search/resolution exports or by the SSSOM ``other`` synonym channel.
NON_RESOLVING_SYNONYM_TYPES = frozenset({"REJECTED_LABEL"})

# Curation strings that live in ``synonyms`` but are not names anything answers
# to: role/property annotations carried over from the CultureMech import,
# CultureMech original-amount notes, and bare parentheticals like
# ``(sodium salt)`` or ``(for solid medium, alternative)`` that are fragments of
# a name, not a name. Publishing them as resolvable labels would make internal
# notes resolve to real ingredients.
_CURATION_NOTE_SYNONYM_TEXT = r"^\s*(?:role|properties|cross-references?|original amount)\s*:"
# Organism assay assertions name a relationship to an ingredient, not the
# ingredient itself (#703). Require the complete prefix and colon: chemical
# ratios, CURIEs, and names such as "reduction indicator" remain valid labels.
_TRAIT_SYNONYM_TEXT = (
    r"^\s*(?:produces|reduction|degradation|hydrolysis|electron acceptor|"
    r"aerobic catabolization|anaerobic catabolization|assimilation|growth|"
    r"fermentation|oxidation(?: in darkness)?)\s*:"
)
_BARE_PARENTHETICAL = r"^\s*\([^)]*\)\s*$"

CURATION_NOTE_SYNONYM_TEXT = re.compile(_CURATION_NOTE_SYNONYM_TEXT, re.IGNORECASE)
NON_RESOLVING_SYNONYM_TEXT = re.compile(
    f"{_CURATION_NOTE_SYNONYM_TEXT}|{_TRAIT_SYNONYM_TEXT}|{_BARE_PARENTHETICAL}",
    re.IGNORECASE,
)


def is_curation_note_synonym_text(text: Any) -> bool:
    """Return whether synonym text is an importer or curator note."""
    if not text:
        return False
    return bool(CURATION_NOTE_SYNONYM_TEXT.match(str(text)))


def is_resolving_synonym_text(text: Any) -> bool:
    """Return whether synonym text is a real label for a record."""
    if not text:
        return False
    return not NON_RESOLVING_SYNONYM_TEXT.match(str(text))


def is_resolving_synonym(synonym: Mapping[str, Any]) -> bool:
    """Return whether a synonym row is allowed to resolve to its record."""
    synonym_type = str(synonym.get("synonym_type") or "").strip().upper()
    if synonym_type in NON_RESOLVING_SYNONYM_TYPES:
        return False
    return is_resolving_synonym_text(synonym.get("synonym_text"))


def preferred_term_owners(records: Mapping[str, Mapping[str, Any]]) -> dict[str, frozenset[str]]:
    """Native Rule K ownership, including credited or unresolved tombstones.

    Callers supply the complete mapped-directory snapshot, keyed by forward
    escaped MIM subjects. An explicit representative takes precedence even when
    empty or unresolved; only an absent representative permits legacy fallback.
    """

    def rejected(data: Mapping[str, Any]) -> bool:
        return str(data.get("mapping_status") or "").strip().upper() == "REJECTED"

    live_by_identifier: dict[str, set[str]] = {}
    for subject, data in records.items():
        identifier = str(data.get("identifier") or "").strip()
        if identifier and not rejected(data):
            live_by_identifier.setdefault(identifier, set()).add(subject)
    owners: dict[str, set[str]] = {}
    for subject, data in records.items():
        term = str(data.get("preferred_term") or "").strip()
        if not term:
            continue
        if rejected(data):
            target = (
                data.get("representative") if "representative" in data else data.get("identifier")
            )
            credited = live_by_identifier.get(str(target or "").strip())
            owners.setdefault(term.casefold(), set()).update(credited or {subject})
        else:
            owners.setdefault(term.casefold(), set()).add(subject)
    return {term: frozenset(subjects) for term, subjects in owners.items()}

"""The registry of in-place corpus writers, and the guard that keeps it honest.

Phase 3 items 2 and 5. The acceptance criterion is that every registered writer
either uses the shared transaction or carries a reviewed, time-bounded
exception, and that a new unmanaged writer cannot be added silently.

Scope is deliberately narrow and stated rather than inferred: this registry
tracks callers of the shared `write_yaml` record helper. That helper writes a
record dict straight to a path with `open(path, "w")`, so every caller is an
in-place, non-atomic corpus writer, and it is the concrete migration debt left
by keeping `write_yaml` when `classify_ingredient_type` moved to the
transaction.

It is NOT a general "does this script mutate a Mech" detector. Deciding that
needs dataflow analysis -- whether a write target derives from a Mech root --
and a regex approximation of it is wrong in both directions: a first attempt
here flagged `generate_mapping_taxonomy_report` (writes a report),
`fetch_pubmed_abstracts` (writes a cache), and `publish_sssom` (writes a temp
file) as corpus writers purely because each mentions a Mech root elsewhere.
Registering those would have asserted something false. The wider detector is
tracked separately; this covers the surface it can cover honestly.
"""

from __future__ import annotations

import ast
from dataclasses import dataclass
from datetime import date
from pathlib import Path
from typing import Any

import yaml

REGISTRY_FILENAME = "writers.yaml"
REGISTRY_VERSION = 1

# Detection is AST-based, generalizing the strongest of the per-Mech writer
# audits (ProteinTraitsMech's, which resolves imports and inspects call nodes
# rather than matching text). The regex it replaces produced two defects in one
# session: a fixed-width `(?<!def )` lookbehind that read `def  write_yaml(` as
# a call (#171), and matching the NAME so a module defining its own same-named
# helper was registered as a corpus writer (#172). Both are classes a parser
# does not have.
SHARED_WRITER_MODULE = "classify_ingredient_type"
SHARED_WRITER_NAME = "write_yaml"

STATUSES = frozenset({"transaction", "exception"})


class RegistryError(ValueError):
    """The writer registry is malformed, or disagrees with the repository."""


@dataclass(frozen=True)
class WriterEntry:
    """One declared in-place corpus writer."""

    path: str
    status: str
    targets: str
    reason: str = ""
    review_by: date | None = None

    @property
    def uses_transaction(self) -> bool:
        return self.status == "transaction"


def _local_name_for_shared_writer(tree: ast.AST) -> str | None:
    """The local name the shared helper is bound to, or None if not imported.

    Follows `as` renaming, which text matching cannot: `from … import write_yaml
    as _w` then `_w(path, record)` is a call to the shared helper and reads
    nothing like one.
    """
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.module == SHARED_WRITER_MODULE:
            for alias in node.names:
                if alias.name == SHARED_WRITER_NAME:
                    return alias.asname or alias.name
    return None


def _module_names_for_shared_writer(tree: ast.AST) -> set[str]:
    """Names the writer's MODULE is bound to by a plain `import` (#185).

    `import classify_ingredient_type as m` then `m.write_yaml(...)` reaches the
    same function as a from-import, and a detector that only understood one of
    the two forms could be evaded by writing ordinary Python.
    """
    names: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name == SHARED_WRITER_MODULE:
                    names.add(alias.asname or alias.name)
    return names


def calls_shared_record_writer(source: str) -> bool:
    """Whether this module calls the shared `write_yaml` record helper.

    Both halves are required: the module must import the shared helper AND call
    it under whatever name it bound. A same-named local function is not the
    shared helper however identical the call site looks (#172), and a defining
    module is not a calling one (#171). Both import forms count -- a
    from-import of the function and a plain import of its module (#185).

    Known limit, stated rather than papered over: an indirect binding such as
    `f = write_yaml; f(path, record)` is NOT detected. Following a value
    through arbitrary rebinding is dataflow analysis rather than a parse, and a
    detector that claimed to catch it would be promising what it cannot do.
    """
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return False

    local_name = _local_name_for_shared_writer(tree)
    module_names = _module_names_for_shared_writer(tree)
    if local_name is None and not module_names:
        return False

    # A module-level def of the same name shadows the import from that point
    # on, so the binding no longer refers to the shared helper.
    if local_name is not None and any(
        isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name == local_name
        for node in tree.body
    ):
        local_name = None

    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        if local_name is not None and getattr(func, "id", None) == local_name:
            return True
        if (
            isinstance(func, ast.Attribute)
            and func.attr == SHARED_WRITER_NAME
            and getattr(func.value, "id", None) in module_names
        ):
            return True
    return False


def discover_corpus_writers(root: Path) -> set[str]:
    """Every `write_yaml` caller under `root`, as repository-relative paths."""
    found: set[str] = set()
    for path in sorted((root / "scripts").glob("*.py")):
        try:
            source = path.read_text(encoding="utf-8")
        except OSError:  # pragma: no cover - unreadable file in a checkout
            continue
        if calls_shared_record_writer(source):
            found.add(str(path.relative_to(root)))
    return found


def parse_registry(data: Any) -> dict[str, WriterEntry]:
    """Validate a loaded registry document."""
    if not isinstance(data, dict):
        raise RegistryError("writer registry must be a YAML mapping")
    version = data.get("version")
    if version != REGISTRY_VERSION:
        raise RegistryError(
            f"unsupported writer registry version {version!r}; "
            f"expected {REGISTRY_VERSION}"
        )
    raw_writers = data.get("writers")
    if not isinstance(raw_writers, dict) or not raw_writers:
        raise RegistryError("writer registry requires a non-empty 'writers' mapping")

    entries: dict[str, WriterEntry] = {}
    for path, raw in raw_writers.items():
        if not isinstance(raw, dict):
            raise RegistryError(f"writer {path!r} must be a mapping")
        status = raw.get("status")
        if status not in STATUSES:
            raise RegistryError(
                f"writer {path!r} has status {status!r}; expected one of "
                f"{', '.join(sorted(STATUSES))}"
            )
        targets = raw.get("targets")
        if not isinstance(targets, str) or not targets.strip():
            raise RegistryError(f"writer {path!r} must declare what it targets")

        reason = raw.get("reason", "")
        review_by = raw.get("review_by")
        if status == "exception":
            # A time-bounded, reasoned exception -- not an indefinite opt-out.
            if not isinstance(reason, str) or not reason.strip():
                raise RegistryError(
                    f"writer {path!r} claims an exception without a reason"
                )
            if not isinstance(review_by, date):
                raise RegistryError(
                    f"writer {path!r} claims an exception without a review_by "
                    f"date; an untimed exception is a permanent one"
                )
        else:
            if review_by is not None:
                raise RegistryError(
                    f"writer {path!r} uses the transaction and needs no review_by"
                )
        entries[str(path)] = WriterEntry(
            path=str(path),
            status=status,
            targets=targets.strip(),
            reason=reason.strip() if isinstance(reason, str) else "",
            review_by=review_by if isinstance(review_by, date) else None,
        )
    return entries


def default_registry_path() -> Path:
    return Path(__file__).resolve().parent / REGISTRY_FILENAME


def load_registry(path: Path | None = None) -> dict[str, WriterEntry]:
    """Read and validate the packaged writer registry."""
    target = Path(path) if path is not None else default_registry_path()
    try:
        text = target.read_text(encoding="utf-8")
    except OSError as exc:
        raise RegistryError(f"cannot read writer registry {target}: {exc}") from exc
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError as exc:
        raise RegistryError(f"writer registry {target} is not valid YAML: {exc}") from exc
    return parse_registry(data)


def overdue(entries: dict[str, WriterEntry], today: date) -> list[WriterEntry]:
    """Exceptions whose review date has passed."""
    return sorted(
        (
            entry
            for entry in entries.values()
            if entry.status == "exception"
            and entry.review_by is not None
            and entry.review_by < today
        ),
        key=lambda entry: entry.path,
    )

"""Publish one diagnostic SSSOM artifact set with the native write transaction.

This is working-copy publication, not approval or canonical MIM promotion.
Replacement is recoverable through a native journal; multiple renames are not
one filesystem-atomic operation. Source discovery and chemistry stay in the
builder, which supplies an exact snapshot checker.
"""

from __future__ import annotations

import csv
import hashlib
import importlib.util
import io
import json
import os
import stat
import unicodedata
from collections.abc import Callable, Iterable, Mapping
from pathlib import Path

from kg_microbe_utils.owned_name_policy import POLICY_VERSION
from kg_microbe_write import ValidatedWriteTransaction
from kg_microbe_write.transaction import JOURNAL_VERSION

POLICY_MARKER = "owned-name-policy-v1; suppression-sidecar-required"


def checked_path(path: Path) -> Path:
    """Reject traversal/symlink spellings before any lexical normalization."""
    path = Path(path)
    if ".." in path.parts:
        raise ValueError(f"Parent traversal in artifact/input path refused: {path}")
    for entry in (path, *path.parents):
        if entry.is_symlink():
            raise ValueError(f"Symlink artifact/input path refused: {entry}")
    return Path(os.path.abspath(path))


def artifact_paths(
    output: Path, sidecar_output: Path | None = None, manifest_output: Path | None = None,
) -> tuple[Path, Path, Path]:
    """Return explicit artifact paths without resolving away an alias."""
    output = checked_path(output)
    return (
        output,
        checked_path(sidecar_output or output.with_name("suppressed_aliases.tsv")),
        checked_path(manifest_output or output.with_suffix(output.suffix + ".manifest.json")),
    )


def _check_path(path: Path) -> bool:
    for entry in (path, *path.parents):
        if entry.is_symlink():
            raise ValueError(f"Symlink artifact/input path refused: {entry}")
    try:
        info = path.lstat()
    except FileNotFoundError:
        return False
    if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
        raise ValueError(f"Expected a regular, unaliased file: {path}")
    return True


def _regular(path: Path) -> bytes | None:
    return path.read_bytes() if _check_path(path) else None


def capture_beforeimages(paths: Iterable[Path]) -> dict[Path, bytes | None]:
    return {checked_path(p): _regular(checked_path(p)) for p in paths}


def _load_lock_manager(claw_root: Path):
    source = claw_root / "plugins/lock_manager.py"
    spec = importlib.util.spec_from_file_location("sssom_artifact_lock", source)
    if spec is None or spec.loader is None:
        raise ValueError(f"Cannot load native lock manager: {source}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.LockManager


def _validate_pair(sssom_bytes: bytes, sidecar_bytes: bytes) -> None:
    from kg_microbe_utils.owned_name_policy import SIDECAR_COLUMNS

    text = sssom_bytes.decode("utf-8")
    header = "\n".join(line for line in text.splitlines() if line.startswith("#"))
    if POLICY_MARKER not in header:
        raise ValueError("SSSOM is missing the suppression-sidecar policy marker")
    rows = csv.DictReader(io.StringIO("".join(
        line for line in text.splitlines(keepends=True) if not line.startswith("#")
    )), delimiter="\t")
    if not rows.fieldnames or not {"subject_id", "other"} <= set(rows.fieldnames):
        raise ValueError("SSSOM lacks subject_id/other columns")
    tokens: dict[str, set[str]] = {}
    for row in rows:
        if None in row or None in row.values():
            raise ValueError("Malformed SSSOM row")
        tokens.setdefault(row["subject_id"], set()).update(
            token.strip().casefold() for token in row["other"].split("|") if token.strip()
        )
    reader = csv.DictReader(io.StringIO(sidecar_bytes.decode("utf-8")), delimiter="\t")
    if reader.fieldnames != list(SIDECAR_COLUMNS):
        raise ValueError("Unexpected suppression sidecar columns")
    seen: set[tuple[str, str]] = set()
    for row in reader:
        if None in row or None in row.values():
            raise ValueError("Malformed suppression sidecar row")
        subject, key = row["subject_id"], row["token_key"]
        pair = (subject, key)
        if (not key or "|" in row["token"] or row["token"].strip().casefold() != key or pair in seen
                or row["disposition"] != "SUPPRESS" or subject not in tokens
                or key in tokens[subject]):
            raise ValueError(f"Invalid or still-published suppression pair: {pair}")
        for field in ("owner_subject_ids", "input_surfaces", "source_refs", "evidence_refs"):
            value = json.loads(row[field])
            if (not isinstance(value, list) or not value
                    or any(not isinstance(x, str) or not x.strip() for x in value)
                    or value != sorted(set(value))):
                raise ValueError(f"Invalid suppression provenance: {field}")
            if field == "owner_subject_ids" and subject in value:
                raise ValueError("A subject cannot suppress its own preferred name")
        seen.add(pair)


def publish_candidate_artifacts(
    output: Path, sssom_bytes: bytes, sidecar_bytes: bytes, manifest_body: dict,
    input_check: Callable[[], None], *, input_paths: Iterable[Path],
    expected_before: Mapping[Path, bytes | None], claw_root: Path,
    working_copy_stamp_input: bool = False, sidecar_output: Path | None = None,
    manifest_output: Path | None = None,
) -> dict:
    """Validate, lock, journal and verify the complete working-copy artifact set.

    The only permitted input/output overlap is the explicitly declared SSSOM
    working-copy stamp beforeimage. The callback must check all other source
    bytes and complete source path sets; it runs before and after publication.
    """
    paths = artifact_paths(output, sidecar_output, manifest_output)
    before = {checked_path(p): b for p, b in expected_before.items()}
    if len(set(paths)) != 3 or set(before) != set(paths):
        raise ValueError("Three distinct destinations and exact beforeimages are required")
    # Be portable even when files do not yet exist (#703). A case-sensitive
    # filesystem may distinguish these spellings, but artifact sets must also
    # be safe on case-insensitive/normalizing filesystems without a write probe.
    def portable_key(path: Path) -> str:
        return unicodedata.normalize("NFC", str(path)).casefold()

    if len({portable_key(p) for p in paths}) != 3:
        raise ValueError("Case/Unicode-equivalent artifact destinations are aliases")
    if len({p.parent for p in paths}) != 1:
        raise ValueError("Candidate artifacts must have the same parent directory")
    inputs = tuple(checked_path(p) for p in input_paths)
    overlap = set(inputs) & set(paths)
    allowed = {paths[0]} if working_copy_stamp_input else set()
    if overlap - allowed or (working_copy_stamp_input and paths[0] not in inputs):
        raise ValueError("Unexpected input/output alias or undeclared working-copy input")
    for path in paths:
        for source in inputs:
            if path == source and path in allowed:
                continue
            if portable_key(path) == portable_key(source):
                raise ValueError(f"Case/Unicode input/output alias: {path} and {source}")
    for path in (*paths, *inputs):
        _check_path(path)
    for index, path in enumerate(paths):
        for other in (*paths[index + 1:], *inputs):
            if path == other and path in allowed:
                continue
            if path.exists() and other.exists() and path.samefile(other):
                raise ValueError(f"Filesystem input/output alias: {path} and {other}")
    for content in before.values():
        if content is not None:
            # Native journals preserve text. Refuse a beforeimage that text
            # decoding/newline conversion would not recover byte-for-byte.
            content.decode("utf-8")
            if b"\r" in content:
                raise ValueError("Artifact beforeimages must use UTF-8/LF")
    if {"schema_version", "policy_version", "artifacts"} & manifest_body.keys():
        raise ValueError("Generation manifest body contains reserved artifact fields")
    _validate_pair(sssom_bytes, sidecar_bytes)
    manifest = {
        **manifest_body, "schema_version": 1, "policy_version": POLICY_VERSION,
        "artifacts": [
            {"role": role, "path": str(path), "sha256": hashlib.sha256(content).hexdigest()}
            for role, path, content in zip(
                ("sssom", "suppressed_aliases"), paths, (sssom_bytes, sidecar_bytes), strict=False
            )
        ],
    }
    manifest_bytes = (json.dumps(manifest, indent=2, sort_keys=True, ensure_ascii=False) + "\n").encode()
    intended = dict(zip(paths, (sssom_bytes, sidecar_bytes, manifest_bytes), strict=True))
    journal_dir = paths[0].parent / ".sssom-artifact-journals"

    def check_journal_path() -> None:
        checked_path(journal_dir)
        if journal_dir.exists() and not journal_dir.is_dir():
            raise ValueError(f"Journal path is not a directory: {journal_dir}")

    def check_before() -> None:
        for path in inputs:
            _check_path(path)
        input_check()
        check_journal_path()
        # Hashing the sources may take time. Recheck destinations afterward,
        # including the no-op and final native precommit boundary (#704).
        for path, content in before.items():
            if _regular(path) != content:
                raise ValueError(f"Artifact beforeimage changed: {path}")

    def validate_staged(path: Path, text: str) -> None:
        if text.encode("utf-8") != intended[path]:
            raise ValueError(f"Staged artifact changed: {path}")
        check_before()

    locker = _load_lock_manager(Path(claw_root))()
    with locker.lock("mediaingredientmech", "build owned-name SSSOM candidate"):
        check_before()
        if all(before[p] == content for p, content in intended.items()):
            return {"status": "unchanged", "artifacts": manifest["artifacts"],
                    "manifest_sha256": hashlib.sha256(manifest_bytes).hexdigest(), "journal": None}
        paths[0].parent.mkdir(parents=True, exist_ok=True)
        # Recheck directory identity after creation; resolve() must not silently
        # turn a newly introduced symlink into a different write destination.
        check_before()
        transaction = ValidatedWriteTransaction(
            root=paths[0].parent, validator=validate_staged,
            journal_dir=journal_dir,
        )
        for path, content in intended.items():
            transaction.stage(path, content.decode("utf-8"))
        result = transaction.commit(apply=True)
        changed = sorted(p for p in paths if before[p] is not None and before[p] != intended[p])
        created = sorted(p for p in paths if before[p] is None)
        unchanged = sorted(p for p in paths if before[p] == intended[p])
        if (result.applied is not True or list(result.changed) != changed
                or list(result.created) != created or list(result.unchanged) != unchanged
                or result.journal_path is None
                or checked_path(result.journal_path).parent != journal_dir):
            raise ValueError("Native transaction result is not bound to the intended artifact set")
        journal_before_check = _regular(result.journal_path)
        previous = {}
        for path in changed:
            old_content = before[path]
            if old_content is None:
                raise ValueError(f"Changed artifact is missing its beforeimage: {path}")
            previous[str(path)] = old_content.decode("utf-8")
        expected_journal = {
            "version": JOURNAL_VERSION, "root": str(paths[0].parent), "status": "complete",
            "changed": [str(p) for p in changed], "created": [str(p) for p in created],
            "previous": previous,
        }
        expected_journal_bytes = json.dumps(expected_journal, indent=2, sort_keys=True).encode("utf-8")
        if journal_before_check != expected_journal_bytes:
            raise ValueError(f"Missing or invalid completed recovery journal: {result.journal_path}")
        input_check()
        check_journal_path()
        if _regular(result.journal_path) != journal_before_check:
            raise ValueError(f"Completed recovery journal changed: {result.journal_path}")
        for path, content in intended.items():
            if _regular(path) != content:
                raise ValueError(f"Artifact publication mismatch: {path}; journal={result.journal_path}")
        return {"status": "complete", **result.as_dict(), "artifacts": manifest["artifacts"],
                "manifest_sha256": hashlib.sha256(manifest_bytes).hexdigest()}

"""Canonical fleet manifest: the one list of Mech repositories.

Every fleet-facing component must derive its repository list from
``src/kg_microbe_fleet/fleet.yaml`` through this module. Independent lists are how
ProteinTraitsMech came to be missing from core configuration while appearing in
the fleet PR sweep, and how the cross-Mech sync skill settled on a fourth
repository set of its own.

The loader validates fail-closed. A malformed manifest raises rather than
yielding a partial fleet, because a silently short repository list is
indistinguishable from a correct one at the call site.
"""

from __future__ import annotations

import os
import re
from dataclasses import dataclass, field
from functools import lru_cache
from math import isfinite
from pathlib import Path, PurePosixPath
from types import MappingProxyType
from typing import Any, Mapping, Optional

import yaml  # type: ignore[import-untyped]

__all__ = [
    "FleetManifestError",
    "CapabilitySettingDefinition",
    "CapabilityDefinition",
    "Capability",
    "ReasonClaims",
    "REASON_CLAIM_SCOPES",
    "MechDefinition",
    "VendoredGovernance",
    "FleetManifest",
    "load_fleet_manifest",
    "default_manifest_path",
    "default_fleet_pull_schema_path",
    "FLEET_PULL_SCHEMA_FILENAME",
    "CAPABILITY_STATUSES",
    "STATUSES_REQUIRING_REASON",
    "VENDORED_ROLES",
    "VENDORED_GOVERNANCE_STATES",
    "UniqueKeySafeLoader",
]

# The manifest ships *inside* this package rather than at the repository root.
# Installed console commands need it after the source checkout is absent; it is
# declared in ``[tool.setuptools.package-data]``. Consumers load a snapshot at
# command time and may inject that same object into repository settings.
MANIFEST_ENVIRONMENT_VARIABLE = "KG_MICROBE_FLEET_MANIFEST"
MANIFEST_FILENAME = "fleet.yaml"
FLEET_PULL_SCHEMA_FILENAME = "schema/fleet_pull.yaml"

CAPABILITY_STATUSES = frozenset({"enabled", "disabled", "not_applicable"})
# A capability that is off must say why. Without this, "absent" and
# "deliberately excluded" look identical in the manifest.
STATUSES_REQUIRING_REASON = frozenset({"disabled", "not_applicable"})
VENDORED_ROLES = frozenset({"hub", "spoke", "consumer"})
VENDORED_GOVERNANCE_STATES = frozenset({"transition", "authoritative"})
SETTING_TYPES = frozenset(
    {"boolean", "integer", "number", "string", "string_list"}
)

SUPPORTED_VERSIONS = frozenset({1})

_IDENTIFIER_PATTERN = re.compile(r"^[a-z][a-z0-9_]*$")
_ENVIRONMENT_VARIABLE_PATTERN = re.compile(r"^[A-Z][A-Z0-9_]*$")
_GITHUB_IDENTITY_PATTERN = re.compile(
    r"^[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?/"
    r"[A-Za-z0-9_.-]+$"
)


class UniqueKeySafeLoader(yaml.SafeLoader):  # type: ignore[misc]
    """Safe YAML loader that rejects keys PyYAML would silently overwrite."""

    def construct_mapping(self, node: Any, deep: bool = False) -> dict[Any, Any]:
        if not isinstance(node, yaml.MappingNode):
            raise yaml.constructor.ConstructorError(
                None,
                None,
                "expected a mapping node",
                node.start_mark,
            )

        # Expand YAML merge keys before checking so an explicit key cannot
        # silently override a value inherited through ``<<`` either.
        self.flatten_mapping(node)
        mapping: dict[Any, Any] = {}
        for key_node, value_node in node.value:
            key = self.construct_object(key_node, deep=deep)
            try:
                duplicate = key in mapping
            except TypeError as exc:
                raise yaml.constructor.ConstructorError(
                    "while constructing a mapping",
                    node.start_mark,
                    "found an unhashable key",
                    key_node.start_mark,
                ) from exc
            if duplicate:
                raise yaml.constructor.ConstructorError(
                    "while constructing a mapping",
                    node.start_mark,
                    f"found duplicate key {key!r}",
                    key_node.start_mark,
                )
            mapping[key] = self.construct_object(value_node, deep=deep)
        return mapping


class FleetManifestError(ValueError):
    """Raised when the fleet manifest cannot be trusted."""


@dataclass(frozen=True)
class CapabilitySettingDefinition:
    """Validation contract for one capability setting."""

    name: str
    value_type: str
    required_when_enabled: bool = False
    minimum: Optional[float] = None


@dataclass(frozen=True)
class CapabilityDefinition:
    """One capability in the fleet-wide catalogue."""

    name: str
    settings: Mapping[str, CapabilitySettingDefinition]


@dataclass(frozen=True)
class ReasonClaims:
    """The checkable half of a capability's `reason`.

    A reason is prose about another repository -- the file it fetches through,
    the workflow it builds with, the catalogue it does not keep -- and prose
    rots silently. #236 found one that named a `generate-pages.yaml` TraitMech
    does not have; the sentence had been copied from the three Mechs that do.

    Rather than parse the English, a reason declares which paths it is asserting
    about and in which direction. `absent` matters as much as `present`: half
    these reasons exist to say a Mech has *no* download.yaml, and a check that
    only confirmed existence would have nothing to say about them.

    A path is read in the Mech the declaration belongs to unless it carries the
    `claw:` prefix, for the reasons that name one of this repository's own
    scripts.
    """

    present: tuple[str, ...] = ()
    absent: tuple[str, ...] = ()

    def __bool__(self) -> bool:
        return bool(self.present or self.absent)


@dataclass(frozen=True)
class Capability:
    """A capability declaration for one repository."""

    name: str
    status: str
    reason: Optional[str] = None
    settings: Mapping[str, Any] = field(
        default_factory=lambda: MappingProxyType({})
    )
    reason_claims: ReasonClaims = field(default_factory=ReasonClaims)

    @property
    def is_enabled(self) -> bool:
        return self.status == "enabled"


@dataclass(frozen=True)
class Serialization:
    """How a Mech's records must be re-emitted so a write is not a reformat.

    `verified` means the options were measured to round-trip that Mech's real
    corpus byte-for-byte, not merely copied from its writer. Two Mechs have no
    option set that reproduces theirs (#187), so they declare `verified: false`
    with a reason and carry no options at all -- there is no correct value, and
    guessing one would reformat a corpus on the next write.
    """

    verified: bool
    options: Mapping[str, object] = field(default_factory=dict)
    reason: str = ""


@dataclass(frozen=True)
class MechDefinition:
    """Identity and declared capabilities for one Mech repository."""

    key: str
    display_name: str
    github: str
    environment_variable: str
    package_path: str
    schema_paths: tuple[str, ...]
    record_globs: tuple[str, ...]
    vendored_role: str
    capabilities: Mapping[str, Capability]
    serialization: Optional["Serialization"] = None

    def capability(self, name: str) -> Optional[Capability]:
        return self.capabilities.get(name)

    def supports(self, name: str) -> bool:
        """Return whether ``name`` is declared enabled for this repository.

        An undeclared capability is not enabled. Treating "unmentioned" as
        "available" is what lets a capability quietly apply to a repository it
        was never verified against.
        """

        capability = self.capabilities.get(name)
        return capability is not None and capability.is_enabled


@dataclass(frozen=True)
class VendoredGovernance:
    """Authority and rollout state for shared, deliberately vendored artifacts.

    During the coordinated Phase 1 migration, ``legacy_hub`` identifies the
    former Mech authority that old pins still consume.  In the authoritative
    state claw is external to the Mech fleet, every Mech is a consumer, and no
    Mech may retain a hub role.
    """

    state: str
    canonical_repository: str
    manifest_path: str
    pin_path: str
    legacy_hub: Optional[str] = None


class FleetManifest:
    """The validated fleet definition."""

    def __init__(
        self,
        mechs: Mapping[str, MechDefinition],
        capability_catalogue: Mapping[str, CapabilityDefinition],
        vendored_governance: VendoredGovernance,
        source: Path,
    ) -> None:
        self._mechs = dict(mechs)
        self._capability_catalogue = dict(capability_catalogue)
        self._vendored_governance = vendored_governance
        self._source = source

    @property
    def source(self) -> Path:
        return self._source

    @property
    def keys(self) -> tuple[str, ...]:
        """Return every Mech key in manifest order."""

        return tuple(self._mechs)

    @property
    def mechs(self) -> dict[str, MechDefinition]:
        return dict(self._mechs)

    @property
    def capability_catalogue(self) -> dict[str, CapabilityDefinition]:
        """Return a copy of the canonical capability catalogue."""

        return dict(self._capability_catalogue)

    @property
    def capability_names(self) -> tuple[str, ...]:
        """Return every catalogue capability in manifest order."""

        return tuple(self._capability_catalogue)

    @property
    def vendored_governance(self) -> VendoredGovernance:
        return self._vendored_governance

    @property
    def vendored_hub(self) -> Optional[str]:
        """Return the temporary legacy Mech hub, if the migration still has one."""

        return self._vendored_governance.legacy_hub

    def get(self, key: str) -> MechDefinition:
        try:
            return self._mechs[key]
        except KeyError:
            known = ", ".join(sorted(self._mechs))
            raise FleetManifestError(
                f"Unknown Mech '{key}'; known Mechs: {known}"
            ) from None

    def environment_variables(self) -> dict[str, str]:
        """Return ``{key: environment variable}`` for every Mech."""

        return {key: mech.environment_variable for key, mech in self._mechs.items()}

    def with_capability(self, name: str) -> tuple[str, ...]:
        """Return the keys of Mechs declaring ``name`` enabled."""

        return tuple(key for key, mech in self._mechs.items() if mech.supports(name))


def default_manifest_path() -> Path:
    """Return the manifest path, honouring the environment override.

    The library reads the real process environment and does not implicitly
    parse ``.env``. Applications that support dotenv must load it before they
    call this function, then pass the returned manifest to all consumers.
    """

    override = os.environ.get(MANIFEST_ENVIRONMENT_VARIABLE)
    if override:
        return Path(override).expanduser()
    return Path(__file__).resolve().parent / MANIFEST_FILENAME


def default_fleet_pull_schema_path() -> Path:
    """Return the path to the packaged fleet-pull LinkML schema."""

    return Path(__file__).resolve().parent / FLEET_PULL_SCHEMA_FILENAME


def _require_mapping(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise FleetManifestError(f"{label} must be a mapping")
    return value


def _require_identity(value: Any, label: str) -> str:
    if (
        not isinstance(value, str)
        or not _GITHUB_IDENTITY_PATTERN.fullmatch(value)
        or value.rsplit("/", 1)[-1] in {".", ".."}
    ):
        raise FleetManifestError(f"{label} must be 'owner/repository'")
    return value


def _require_nonempty_string(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise FleetManifestError(f"{label} must be a non-empty string")
    return value.strip()


def _require_identifier(value: Any, label: str) -> str:
    if not isinstance(value, str) or not _IDENTIFIER_PATTERN.fullmatch(value):
        raise FleetManifestError(
            f"{label} must start with a lowercase letter and contain only "
            "lowercase letters, digits, and underscores"
        )
    return value


def _require_environment_variable(value: Any, label: str) -> str:
    if not isinstance(value, str) or not _ENVIRONMENT_VARIABLE_PATTERN.fullmatch(value):
        raise FleetManifestError(f"{label} must be an uppercase environment variable")
    return value


def _require_relative_path(value: Any, label: str, *, glob: bool = False) -> str:
    text = _require_nonempty_string(value, label)
    if "\\" in text:
        raise FleetManifestError(f"{label} must be a repository-relative POSIX path")
    segments = text.split("/")
    path = PurePosixPath(text)
    if path.is_absolute() or any(segment in {"", ".", ".."} for segment in segments):
        raise FleetManifestError(
            f"{label} must be a repository-relative path without traversal"
        )

    has_glob = any(character in text for character in "*?[")
    if glob:
        if not has_glob:
            raise FleetManifestError(f"{label} must contain a glob pattern")
        if not text.lower().endswith((".yaml", ".yml")):
            raise FleetManifestError(f"{label} must select YAML records")
    elif has_glob:
        raise FleetManifestError(f"{label} must not contain glob metacharacters")
    return text


def _require_path_sequence(
    value: Any,
    label: str,
    *,
    glob: bool = False,
) -> tuple[str, ...]:
    if not isinstance(value, list) or not value:
        raise FleetManifestError(f"{label} must be a non-empty list")
    paths = tuple(
        _require_relative_path(item, f"{label}[{index}]", glob=glob)
        for index, item in enumerate(value)
    )
    if len(set(paths)) != len(paths):
        raise FleetManifestError(f"{label} must not contain duplicate paths")
    return paths


def _parse_capability_catalogue(raw: Any) -> dict[str, CapabilityDefinition]:
    mapping = _require_mapping(raw, "capability_catalogue")
    if not mapping:
        raise FleetManifestError("capability_catalogue must not be empty")

    catalogue: dict[str, CapabilityDefinition] = {}
    for raw_name, raw_definition in mapping.items():
        name = _require_identifier(raw_name, "capability_catalogue key")
        label = f"capability_catalogue.{name}"
        definition = _require_mapping(raw_definition, label)
        unknown_definition_keys = set(definition) - {"settings"}
        if unknown_definition_keys:
            unknown = ", ".join(sorted(str(key) for key in unknown_definition_keys))
            raise FleetManifestError(f"{label} has unknown keys: {unknown}")

        raw_settings = definition.get("settings", {})
        settings_mapping = _require_mapping(raw_settings, f"{label}.settings")
        setting_definitions: dict[str, CapabilitySettingDefinition] = {}
        for raw_setting_name, raw_setting_definition in settings_mapping.items():
            setting_name = _require_identifier(
                raw_setting_name, f"{label}.settings key"
            )
            setting_label = f"{label}.settings.{setting_name}"
            setting_definition = _require_mapping(
                raw_setting_definition, setting_label
            )
            unknown_setting_keys = set(setting_definition) - {
                "type",
                "required_when_enabled",
                "minimum",
            }
            if unknown_setting_keys:
                unknown = ", ".join(
                    sorted(str(key) for key in unknown_setting_keys)
                )
                raise FleetManifestError(
                    f"{setting_label} has unknown keys: {unknown}"
                )

            value_type = setting_definition.get("type")
            if not isinstance(value_type, str) or value_type not in SETTING_TYPES:
                allowed = ", ".join(sorted(SETTING_TYPES))
                raise FleetManifestError(
                    f"{setting_label}.type must be one of: {allowed}"
                )
            required = setting_definition.get("required_when_enabled", False)
            if not isinstance(required, bool):
                raise FleetManifestError(
                    f"{setting_label}.required_when_enabled must be a boolean"
                )
            minimum = setting_definition.get("minimum")
            if minimum is not None:
                if value_type not in {"integer", "number"} or not isinstance(
                    minimum, (int, float)
                ) or isinstance(minimum, bool) or (
                    isinstance(minimum, float) and not isfinite(minimum)
                ):
                    raise FleetManifestError(
                        f"{setting_label}.minimum requires an integer or number setting"
                    )

            setting_definitions[setting_name] = CapabilitySettingDefinition(
                name=setting_name,
                value_type=value_type,
                required_when_enabled=required,
                minimum=float(minimum) if minimum is not None else None,
            )

        catalogue[name] = CapabilityDefinition(
            name=name,
            settings=MappingProxyType(setting_definitions),
        )
    return catalogue


def _validate_setting_value(
    value: Any,
    definition: CapabilitySettingDefinition,
    label: str,
) -> Any:
    expected = definition.value_type
    if expected == "string_list":
        if not isinstance(value, list) or not value:
            raise FleetManifestError(
                f"{label} must be a non-empty list of non-empty strings"
            )
        normalized = tuple(
            _require_nonempty_string(item, f"{label}[{index}]")
            for index, item in enumerate(value)
        )
        if len(set(normalized)) != len(normalized):
            raise FleetManifestError(f"{label} must not contain duplicate values")
        return normalized

    valid = {
        "boolean": isinstance(value, bool),
        "integer": isinstance(value, int) and not isinstance(value, bool),
        "number": isinstance(value, (int, float))
        and not isinstance(value, bool)
        and (not isinstance(value, float) or isfinite(value)),
        "string": isinstance(value, str) and bool(value.strip()),
    }[expected]
    if not valid:
        article = "an" if expected == "integer" else "a"
        raise FleetManifestError(f"{label} must be {article} {expected}")
    if definition.minimum is not None and value < definition.minimum:
        raise FleetManifestError(
            f"{label} must be at least {definition.minimum:g}"
        )
    return value


def _parse_capabilities(
    raw: Any,
    mech_key: str,
    catalogue: Optional[Mapping[str, CapabilityDefinition]] = None,
    *,
    require_exact: bool = False,
) -> dict[str, Capability]:
    capabilities: dict[str, Capability] = {}
    if raw is None:
        if require_exact:
            raise FleetManifestError(f"mechs.{mech_key}.capabilities is required")
        return capabilities
    mapping = _require_mapping(raw, f"mechs.{mech_key}.capabilities")

    names = {
        _require_identifier(name, f"mechs.{mech_key}.capabilities key")
        for name in mapping
    }
    if require_exact:
        if catalogue is None:  # pragma: no cover - internal misuse guard
            raise AssertionError("exact capability validation requires a catalogue")
        missing = set(catalogue) - names
        unknown = names - set(catalogue)
        if missing:
            raise FleetManifestError(
                f"mechs.{mech_key}.capabilities is missing declarations: "
                + ", ".join(sorted(missing))
            )
        if unknown:
            raise FleetManifestError(
                f"mechs.{mech_key}.capabilities has unknown declarations: "
                + ", ".join(sorted(unknown))
            )

    for raw_name, declaration in mapping.items():
        name = _require_identifier(raw_name, f"mechs.{mech_key}.capabilities key")
        label = f"mechs.{mech_key}.capabilities.{name}"
        declaration_mapping = _require_mapping(declaration, label)
        unknown_declaration_keys = set(declaration_mapping) - {
            "status",
            "reason",
            "settings",
            "reason_claims",
        }
        if unknown_declaration_keys:
            unknown_keys = ", ".join(
                sorted(str(key) for key in unknown_declaration_keys)
            )
            raise FleetManifestError(f"{label} has unknown keys: {unknown_keys}")
        status = declaration_mapping.get("status")
        # `isinstance` first: a list/dict from YAML is unhashable, and a bare
        # membership test would raise TypeError instead of FleetManifestError.
        if not isinstance(status, str) or status not in CAPABILITY_STATUSES:
            allowed = ", ".join(sorted(CAPABILITY_STATUSES))
            raise FleetManifestError(
                f"{label}.status must be one of: {allowed} (got {status!r})"
            )

        reason_value = declaration_mapping.get("reason")
        reason: Optional[str] = None
        if reason_value is not None:
            reason = _require_nonempty_string(reason_value, f"{label}.reason")

        if status in STATUSES_REQUIRING_REASON and not reason:
            raise FleetManifestError(
                f"{label}.reason is required when status is '{status}'"
            )

        reason_claims = _parse_reason_claims(
            declaration_mapping.get("reason_claims"), f"{label}.reason_claims"
        )
        if reason_claims and reason is None:
            raise FleetManifestError(
                f"{label}.reason_claims has nothing to check: there is no reason"
            )

        raw_settings = declaration_mapping.get("settings", {})
        settings_mapping = _require_mapping(raw_settings, f"{label}.settings")
        settings = dict(settings_mapping)
        if catalogue is not None and name in catalogue:
            setting_definitions = catalogue[name].settings
            unknown_settings = set(settings) - set(setting_definitions)
            if unknown_settings:
                raise FleetManifestError(
                    f"{label}.settings has unknown keys: "
                    + ", ".join(sorted(str(key) for key in unknown_settings))
                )
            if status == "enabled":
                missing_settings = {
                    setting_name
                    for setting_name, definition in setting_definitions.items()
                    if definition.required_when_enabled and setting_name not in settings
                }
                if missing_settings:
                    raise FleetManifestError(
                        f"{label}.settings is missing required keys: "
                        + ", ".join(sorted(missing_settings))
                    )
            for setting_name, value in settings.items():
                settings[setting_name] = _validate_setting_value(
                    value,
                    setting_definitions[setting_name],
                    f"{label}.settings.{setting_name}",
                )

        capabilities[name] = Capability(
            name=name,
            status=status,
            reason=reason,
            settings=MappingProxyType(settings),
            reason_claims=reason_claims,
        )

    return capabilities


# The only scope a claim may name other than the Mech's own checkout. Two
# reasons describe a claw script rather than anything in the Mech.
REASON_CLAIM_SCOPES = frozenset({"claw"})


def _parse_reason_claims(raw: Any, label: str) -> ReasonClaims:
    if raw is None:
        return ReasonClaims()
    mapping = _require_mapping(raw, label)
    unknown = set(mapping) - {"present", "absent"}
    if unknown:
        raise FleetManifestError(
            f"{label} has unknown keys: " + ", ".join(sorted(str(k) for k in unknown))
        )
    parsed: dict[str, tuple[str, ...]] = {}
    for direction in ("present", "absent"):
        values = mapping.get(direction, [])
        if not isinstance(values, list):
            raise FleetManifestError(f"{label}.{direction} must be a list")
        paths = []
        for index, value in enumerate(values):
            path = _require_nonempty_string(value, f"{label}.{direction}[{index}]")
            setting_label = f"{label}.{direction}[{index}]"
            # Split the scope off *before* checking containment. Checking the
            # raw string first leaves the hole this guard exists to close:
            # "claw:/etc/passwd" does not start with "/", so it passed, and the
            # consumer then strips the prefix and resolves an absolute path.
            scope, _, relative = path.partition(":")
            if not relative:
                scope, relative = "", path
            elif scope not in REASON_CLAIM_SCOPES:
                allowed = ", ".join(sorted(REASON_CLAIM_SCOPES))
                raise FleetManifestError(
                    f"{setting_label} has unknown scope {scope!r}; allowed: "
                    f"{allowed} (a path in the Mech itself takes no prefix)"
                )
            if relative.startswith("/") or ".." in PurePosixPath(relative).parts:
                raise FleetManifestError(
                    f"{setting_label} must be a path inside the repository, "
                    f"not {path!r}"
                )
            paths.append(path)
        duplicates = {p for p in paths if paths.count(p) > 1}
        if duplicates:
            raise FleetManifestError(
                f"{label}.{direction} repeats: " + ", ".join(sorted(duplicates))
            )
        parsed[direction] = tuple(paths)
    both = set(parsed["present"]) & set(parsed["absent"])
    if both:
        raise FleetManifestError(
            f"{label} claims these are both present and absent: "
            + ", ".join(sorted(both))
        )
    return ReasonClaims(**parsed)


@dataclass(frozen=True)
class _MechIdentity:
    key: str
    display_name: str
    github: str
    environment_variable: str
    vendored_role: str


_SERIALIZATION_KEYS = frozenset({"verified", "options", "reason"})
_ALLOWED_EMIT_OPTIONS = frozenset(
    {"default_flow_style", "sort_keys", "allow_unicode", "width", "indent"}
)


def _parse_serialization(raw: Any, label: str) -> Serialization:
    mapping = _require_mapping(raw, label)
    unknown = set(mapping) - _SERIALIZATION_KEYS
    if unknown:
        raise FleetManifestError(
            f"{label} has unknown keys: {', '.join(sorted(str(k) for k in unknown))}"
        )
    verified = mapping.get("verified")
    if not isinstance(verified, bool):
        raise FleetManifestError(f"{label}.verified must be true or false")

    options = mapping.get("options")
    reason = mapping.get("reason", "")
    if verified:
        options_mapping = _require_mapping(options, f"{label}.options")
        unknown_options = set(options_mapping) - _ALLOWED_EMIT_OPTIONS
        if unknown_options:
            raise FleetManifestError(
                f"{label}.options has unknown keys: "
                f"{', '.join(sorted(str(k) for k in unknown_options))}"
            )
        if not options_mapping:
            raise FleetManifestError(f"{label}.options must not be empty")
        return Serialization(True, dict(options_mapping), "")

    # Unverified: no options, and a recorded reason. An unverified profile that
    # carried options would be exactly the guess this models away from.
    if options:
        raise FleetManifestError(
            f"{label} is unverified and must not declare options; there is no "
            f"correct value to declare"
        )
    if not isinstance(reason, str) or not reason.strip():
        raise FleetManifestError(f"{label} is unverified and requires a reason")
    return Serialization(False, {}, reason.strip())


def _parse_mech_identity(key: str, raw: Any) -> _MechIdentity:
    label = f"mechs.{key}"
    mapping = _require_mapping(raw, label)

    vendored_role = mapping.get("vendored_role")
    if not isinstance(vendored_role, str) or vendored_role not in VENDORED_ROLES:
        allowed = ", ".join(sorted(VENDORED_ROLES))
        raise FleetManifestError(
            f"{label}.vendored_role must be one of: {allowed} (got {vendored_role!r})"
        )

    # Validate declaration syntax before global duplicate/hub checks. Exact
    # catalogue coverage is enforced after those legacy identity invariants so
    # callers receive the most actionable defect first.
    _parse_capabilities(mapping.get("capabilities"), key)
    return _MechIdentity(
        key=key,
        display_name=_require_nonempty_string(
            mapping.get("display_name"), f"{label}.display_name"
        ),
        github=_require_identity(mapping.get("github"), f"{label}.github"),
        environment_variable=_require_environment_variable(
            mapping.get("environment_variable"), f"{label}.environment_variable"
        ),
        vendored_role=vendored_role,
    )


def _parse_mech(
    key: str,
    raw: Any,
    catalogue: Mapping[str, CapabilityDefinition],
) -> MechDefinition:
    label = f"mechs.{key}"
    mapping = _require_mapping(raw, label)
    allowed_keys = {
        "display_name",
        "github",
        "environment_variable",
        "package_path",
        "schema_paths",
        "record_globs",
        "vendored_role",
        "capabilities",
        "serialization",
    }
    unknown_keys = set(mapping) - allowed_keys
    if unknown_keys:
        unknown = ", ".join(sorted(str(item) for item in unknown_keys))
        raise FleetManifestError(f"{label} has unknown keys: {unknown}")

    identity = _parse_mech_identity(key, mapping)
    serialization = (
        _parse_serialization(mapping["serialization"], f"{label}.serialization")
        if "serialization" in mapping
        else None
    )
    schema_paths = _require_path_sequence(
        mapping.get("schema_paths"), f"{label}.schema_paths"
    )
    for index, schema_path in enumerate(schema_paths):
        if not schema_path.lower().endswith((".yaml", ".yml")):
            raise FleetManifestError(
                f"{label}.schema_paths[{index}] must identify a YAML schema"
            )
    record_globs = _require_path_sequence(
        mapping.get("record_globs"), f"{label}.record_globs", glob=True
    )
    capabilities = _parse_capabilities(
        mapping.get("capabilities"),
        key,
        catalogue,
        require_exact=True,
    )
    coverage = capabilities.get("environment_coverage")
    if coverage is not None and "record_globs" in coverage.settings:
        coverage_globs = tuple(
            _require_relative_path(
                pattern,
                f"{label}.capabilities.environment_coverage.settings."
                f"record_globs[{index}]",
                glob=True,
            )
            for index, pattern in enumerate(coverage.settings["record_globs"])
        )
        outside_profile = set(coverage_globs) - set(record_globs)
        if outside_profile:
            raise FleetManifestError(
                f"{label}.capabilities.environment_coverage.settings."
                "record_globs must be a subset of the Mech record_globs profile: "
                + ", ".join(sorted(outside_profile))
            )

    return MechDefinition(
        key=identity.key,
        display_name=identity.display_name,
        github=identity.github,
        environment_variable=identity.environment_variable,
        package_path=_require_relative_path(
            mapping.get("package_path"), f"{label}.package_path"
        ),
        schema_paths=schema_paths,
        record_globs=record_globs,
        vendored_role=identity.vendored_role,
        capabilities=MappingProxyType(capabilities),
        serialization=serialization,
    )


def _parse_vendored_governance(
    value: Any,
    identities_by_key: Mapping[str, _MechIdentity],
) -> VendoredGovernance:
    """Parse the external authority and the temporary legacy rollout state."""

    mapping = _require_mapping(value, "vendored_governance")
    allowed_keys = {
        "state",
        "canonical_repository",
        "manifest_path",
        "pin_path",
        "legacy_hub",
    }
    unknown_keys = set(mapping) - allowed_keys
    if unknown_keys:
        unknown = ", ".join(sorted(str(key) for key in unknown_keys))
        raise FleetManifestError(
            f"vendored_governance has unknown keys: {unknown}"
        )

    state = _require_nonempty_string(mapping.get("state"), "vendored_governance.state")
    if state not in VENDORED_GOVERNANCE_STATES:
        allowed = ", ".join(sorted(VENDORED_GOVERNANCE_STATES))
        raise FleetManifestError(
            "vendored_governance.state must be one of: "
            f"{allowed} (got {state!r})"
        )

    canonical_repository = _require_nonempty_string(
        mapping.get("canonical_repository"),
        "vendored_governance.canonical_repository",
    )
    if (
        not _GITHUB_IDENTITY_PATTERN.fullmatch(canonical_repository)
        or canonical_repository.rsplit("/", 1)[-1] in {".", ".."}
    ):
        raise FleetManifestError(
            "vendored_governance.canonical_repository must be an "
            "owner/repository GitHub identity"
        )
    if canonical_repository.lower() in {
        identity.github.lower() for identity in identities_by_key.values()
    }:
        raise FleetManifestError(
            "vendored_governance.canonical_repository must be external to the "
            "Mech fleet; a Mech authority would recreate a circular/self pin"
        )

    manifest_path = _require_relative_path(
        mapping.get("manifest_path"), "vendored_governance.manifest_path"
    )
    pin_path = _require_relative_path(
        mapping.get("pin_path"), "vendored_governance.pin_path"
    )

    hubs = [
        key
        for key, identity in identities_by_key.items()
        if identity.vendored_role == "hub"
    ]
    non_consumers = [
        key
        for key, identity in identities_by_key.items()
        if identity.vendored_role != "consumer"
    ]
    legacy_value = mapping.get("legacy_hub")

    if state == "transition":
        if len(hubs) != 1:
            found = ", ".join(sorted(hubs)) or "none"
            raise FleetManifestError(
                "Transition governance must declare exactly one legacy "
                f"vendored hub (found: {found})"
            )
        legacy_hub = _require_nonempty_string(
            legacy_value, "vendored_governance.legacy_hub"
        )
        if legacy_hub != hubs[0]:
            raise FleetManifestError(
                f"vendored_governance.legacy_hub is '{legacy_hub}' but the "
                f"repository declaring vendored_role 'hub' is '{hubs[0]}'"
            )
        invalid_roles = [
            key
            for key, identity in identities_by_key.items()
            if identity.vendored_role not in {"hub", "spoke"}
        ]
        if invalid_roles:
            raise FleetManifestError(
                "Transition governance cannot declare consumer roles before "
                f"the atomic authority flip: {', '.join(sorted(invalid_roles))}"
            )
    else:
        if "legacy_hub" in mapping:
            raise FleetManifestError(
                "Authoritative governance must omit legacy_hub"
            )
        if non_consumers:
            raise FleetManifestError(
                "Authoritative governance requires every Mech to declare "
                f"vendored_role 'consumer': {', '.join(sorted(non_consumers))}"
            )
        legacy_hub = None

    return VendoredGovernance(
        state=state,
        canonical_repository=canonical_repository,
        manifest_path=manifest_path,
        pin_path=pin_path,
        legacy_hub=legacy_hub,
    )


def _validate_vendored_governance_capabilities(
    governance: VendoredGovernance,
    mechs: Mapping[str, MechDefinition],
) -> None:
    """Keep vendored roles and capability availability in one atomic state."""

    for key, mech in mechs.items():
        capability = mech.capability("vendored_sync")
        status = capability.status if capability is not None else None
        if governance.state == "authoritative":
            required_status = "enabled"
            state_role = "an authoritative consumer"
        elif mech.vendored_role == "hub":
            required_status = "not_applicable"
            state_role = "a transition legacy hub"
        else:
            required_status = "enabled"
            state_role = "a transition spoke"
        if status != required_status:
            raise FleetManifestError(
                f"mechs.{key}.capabilities.vendored_sync.status must be "
                f"'{required_status}' for {state_role} (got {status!r})"
            )


def parse_fleet_manifest(document: Any, source: Path) -> FleetManifest:
    """Validate an already-loaded manifest document."""

    mapping = _require_mapping(document, f"Fleet manifest {source}")

    version = mapping.get("version")
    if not isinstance(version, int) or isinstance(version, bool) or (
        version not in SUPPORTED_VERSIONS
    ):
        supported = ", ".join(str(value) for value in sorted(SUPPORTED_VERSIONS))
        raise FleetManifestError(
            f"Fleet manifest {source} version must be one of: {supported} "
            f"(got {version!r})"
        )

    raw_mechs = _require_mapping(mapping.get("mechs"), "mechs")
    if not raw_mechs:
        raise FleetManifestError("Fleet manifest must declare at least one Mech")

    mech_keys = [
        _require_identifier(key, "mechs key")
        for key in raw_mechs
    ]
    identities_by_key = {
        key: _parse_mech_identity(key, raw_mechs[key]) for key in mech_keys
    }

    identities = [mech.github.lower() for mech in identities_by_key.values()]
    if len(set(identities)) != len(identities):
        raise FleetManifestError("Fleet manifest declares a duplicate GitHub identity")

    environment_variables = [
        mech.environment_variable for mech in identities_by_key.values()
    ]
    if len(set(environment_variables)) != len(environment_variables):
        raise FleetManifestError(
            "Fleet manifest declares a duplicate environment variable"
        )

    vendored_governance = _parse_vendored_governance(
        mapping.get("vendored_governance"), identities_by_key
    )

    allowed_top_level_keys = {
        "version",
        "capability_catalogue",
        "vendored_governance",
        "mechs",
    }
    unknown_top_level_keys = set(mapping) - allowed_top_level_keys
    if unknown_top_level_keys:
        unknown = ", ".join(sorted(str(key) for key in unknown_top_level_keys))
        raise FleetManifestError(f"Fleet manifest has unknown keys: {unknown}")

    capability_catalogue = _parse_capability_catalogue(
        mapping.get("capability_catalogue")
    )
    mechs = {
        key: _parse_mech(key, raw_mechs[key], capability_catalogue)
        for key in mech_keys
    }
    _validate_vendored_governance_capabilities(vendored_governance, mechs)
    return FleetManifest(
        mechs=mechs,
        capability_catalogue=capability_catalogue,
        vendored_governance=vendored_governance,
        source=source,
    )


def _load_uncached(path: Path) -> FleetManifest:
    try:
        document = yaml.load(
            path.read_text(encoding="utf-8"),
            Loader=UniqueKeySafeLoader,
        )
    except (OSError, yaml.YAMLError) as exc:
        raise FleetManifestError(
            f"Unable to load fleet manifest {path}: {exc}"
        ) from exc
    return parse_fleet_manifest(document, path)


@lru_cache(maxsize=None)
def _load_cached(resolved: Path) -> FleetManifest:
    return _load_uncached(resolved)


def load_fleet_manifest(path: Optional[Path] = None) -> FleetManifest:
    """Load and validate the fleet manifest.

    Results are cached per resolved path; pass ``path`` explicitly in tests so a
    fixture manifest never collides with the repository's own cache entry.
    """

    resolved = (path or default_manifest_path()).expanduser()
    try:
        resolved = resolved.resolve()
    except OSError as exc:  # pragma: no cover - unusual filesystem failure
        raise FleetManifestError(
            f"Unable to resolve fleet manifest path {resolved}: {exc}"
        ) from exc
    return _load_cached(resolved)


def __getattr__(name: str):
    """Expose the root resolver lazily, avoiding an import cycle at module load."""
    if name in {
        "MechRootError",
        "resolve_mech_root",
        "resolve_kg_microbe_root",
        "require_mech_roots",
        "sibling_default",
        "looks_like",
        "dotenv_value",
    }:
        from . import roots

        return getattr(roots, name)
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

"""Dependency-light queries over the canonical Mech fleet manifest.

Shell scripts, GitHub workflows, skills, and declarative agents use this CLI
instead of embedding their own repository lists. All commands are local and
offline; they only read and validate the packaged manifest.
"""

from __future__ import annotations

import argparse
import json
import sys
from collections.abc import Iterable, Mapping
from pathlib import Path
from typing import Any

from . import FleetManifest, FleetManifestError, MechDefinition, load_fleet_manifest


def _capability_names(manifest: FleetManifest) -> frozenset[str]:
    declared = getattr(manifest, "capability_names", None)
    if declared is not None:
        return frozenset(declared)
    return frozenset(
        name
        for mech in manifest.mechs.values()
        for name in mech.capabilities
    )


def _select(
    manifest: FleetManifest, capability: str | None
) -> tuple[MechDefinition, ...]:
    if capability is None:
        return tuple(manifest.mechs.values())
    if capability not in _capability_names(manifest):
        known = ", ".join(sorted(_capability_names(manifest)))
        raise FleetManifestError(
            f"Unknown fleet capability '{capability}'; known capabilities: {known}"
        )
    return tuple(
        mech for mech in manifest.mechs.values() if mech.supports(capability)
    )


def _tsv_value(value: object, label: str) -> str:
    rendered = str(value)
    if "\t" in rendered or "\n" in rendered or "\r" in rendered:
        raise FleetManifestError(f"{label} is not safe for TSV output")
    return rendered


def _identity(mech: MechDefinition) -> dict[str, Any]:
    return {
        "key": mech.key,
        "display_name": mech.display_name,
        "github": mech.github,
        "environment_variable": mech.environment_variable,
        "package_path": mech.package_path,
        "schema_paths": list(mech.schema_paths),
        "record_globs": list(mech.record_globs),
    }


def _list_command(args: argparse.Namespace, manifest: FleetManifest) -> None:
    mechs = _select(manifest, args.capability)
    if args.format == "json":
        print(json.dumps([_identity(mech) for mech in mechs], sort_keys=True))
        return
    if args.format == "tsv":
        fields = ["key", "display_name", "github", "environment_variable"]
        if args.include_package_path:
            fields.append("package_path")
        for mech in mechs:
            row = _identity(mech)
            print(
                "\t".join(
                    _tsv_value(row[field], f"{mech.key}.{field}")
                    for field in fields
                )
            )
        return
    for mech in mechs:
        print(getattr(mech, args.field))


def _capability_settings(mech: MechDefinition, capability: str) -> Mapping[str, Any]:
    declaration = mech.capability(capability)
    if declaration is None:
        raise FleetManifestError(f"{mech.key} does not declare {capability}")
    settings = getattr(declaration, "settings", {})
    if not isinstance(settings, Mapping):
        raise FleetManifestError(f"{mech.key}.{capability}.settings must be a mapping")
    return settings


def _matrix_command(args: argparse.Namespace, manifest: FleetManifest) -> None:
    rows: list[dict[str, Any]] = []
    mechs = _select(manifest, args.capability)
    if args.scheduled_only:
        definition = manifest.capability_catalogue[args.capability].settings.get("scheduled")
        if definition is None or definition.value_type != "boolean":
            raise FleetManifestError(
                f"Capability '{args.capability}' has no boolean scheduled setting"
            )
    for mech in mechs:
        settings = _capability_settings(mech, args.capability)
        if args.scheduled_only and settings.get("scheduled", True) is False:
            continue
        repository_name = mech.github.rsplit("/", 1)[-1]
        row: dict[str, Any] = {
            "mech": mech.display_name,
            "repository": mech.github,
            "checkout_path": repository_name,
            "workdir": repository_name,
        }
        for name in args.setting:
            if name not in settings:
                raise FleetManifestError(
                    f"{mech.key}.{args.capability}.settings is missing '{name}'"
                )
            row[name] = settings[name]
        rows.append(row)
    if not rows:
        qualifier = " eligible for scheduling" if args.scheduled_only else ""
        raise FleetManifestError(
            f"Capability '{args.capability}' has no enabled Mechs{qualifier}"
        )
    print(json.dumps({"include": rows}, separators=(",", ":"), sort_keys=True))


def _show_command(args: argparse.Namespace, manifest: FleetManifest) -> None:
    if args.field == "vendored_hub":
        legacy_hub = manifest.vendored_hub
        if legacy_hub is None:
            raise FleetManifestError(
                "The fleet has no vendored Mech hub; claw is authoritative"
            )
        print(legacy_hub)
        return
    raise FleetManifestError(f"Unsupported manifest field: {args.field}")


def _scope_command(args: argparse.Namespace, manifest: FleetManifest) -> None:
    """Emit a fixed-column capability snapshot for shell consumers.

    Columns are, in order: key, display name, GitHub identity, environment
    variable, package path, and vendored role.  Unlike composing separate
    ``list`` and ``show`` calls, one scope query cannot observe two different
    manifest snapshots.  Consumers that need a vendored authority can also
    require that the declared hub is a member of the selected capability.
    """

    mechs = _select(manifest, args.capability)
    if not mechs:
        raise FleetManifestError(
            f"Capability '{args.capability}' has no enabled Mechs"
        )
    if args.require_vendored_hub:
        legacy_hub = manifest.vendored_hub
        if legacy_hub is None:
            raise FleetManifestError(
                "The fleet has no vendored Mech hub; claw is authoritative"
            )
        if not any(
            mech.key == legacy_hub and mech.vendored_role == "hub"
            for mech in mechs
        ):
            raise FleetManifestError(
                f"vendored hub '{legacy_hub}' is not in capability "
                f"scope '{args.capability}'"
            )

    for mech in mechs:
        print(
            "\t".join(
                _tsv_value(value, f"{mech.key}.{label}")
                for label, value in (
                    ("key", mech.key),
                    ("display_name", mech.display_name),
                    ("github", mech.github),
                    ("environment_variable", mech.environment_variable),
                    ("package_path", mech.package_path),
                    ("vendored_role", mech.vendored_role),
                )
            )
        )


def _targets_command(args: argparse.Namespace, manifest: FleetManifest) -> None:
    """Emit exact, identity-validated checkout roots for local mutations.

    Unconfigured roots remain visible as an empty final field. A configured
    but untrustworthy root fails the whole query before any row is printed, so
    shell consumers cannot act on a partial fleet.
    """

    # Imported lazily: pure manifest queries remain dependency-light and the
    # repository-settings layer continues to own Git identity validation.
    from plugins.repository_settings import (
        RepositoryConfigurationError,
        RepositorySettings,
        merged_repository_environment,
    )

    mechs = _select(manifest, args.capability)
    environ: Mapping[str, str] | None = None
    if args.dotenv is not None:
        try:
            environ = merged_repository_environment(args.dotenv)
        except RepositoryConfigurationError as exc:
            raise FleetManifestError(str(exc)) from exc
    settings = RepositorySettings.from_environment(
        manifest=manifest,
        environ=environ,
    )
    invalid = {
        mech.key: settings.invalid[mech.key]
        for mech in mechs
        if mech.key in settings.invalid
    }
    if invalid:
        details = "; ".join(f"{key}: {message}" for key, message in invalid.items())
        raise FleetManifestError(f"configured fleet target is untrustworthy: {details}")

    rows: list[str] = []
    for mech in mechs:
        path = (
            ""
            if mech.key in settings.unconfigured
            else str(settings.get_target(mech.key).path)
        )
        rows.append(
            "\t".join(
                _tsv_value(value, f"{mech.key}.{label}")
                for label, value in (
                    ("key", mech.key),
                    ("display_name", mech.display_name),
                    ("github", mech.github),
                    ("environment_variable", mech.environment_variable),
                    ("path", path),
                )
            )
        )
    print("\n".join(rows))


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="kg-microbe-fleet")
    subparsers = parser.add_subparsers(dest="command", required=True)

    list_parser = subparsers.add_parser("list", help="list applicable Mechs")
    list_parser.add_argument("--capability")
    list_parser.add_argument(
        "--format", choices=("lines", "json", "tsv"), default="lines"
    )
    list_parser.add_argument(
        "--field",
        choices=(
            "key",
            "display_name",
            "github",
            "environment_variable",
            "package_path",
        ),
        default="key",
        help="field emitted by the lines format",
    )
    list_parser.add_argument(
        "--include-package-path",
        action="store_true",
        help="append package_path to each TSV row",
    )

    matrix_parser = subparsers.add_parser(
        "matrix", help="render a GitHub Actions include matrix"
    )
    matrix_parser.add_argument("--capability", required=True)
    matrix_parser.add_argument("--setting", action="append", default=[])
    matrix_parser.add_argument(
        "--scheduled-only", action="store_true",
        help="omit explicit scheduled:false declarations; absent settings retain legacy eligibility",
    )

    show_parser = subparsers.add_parser("show", help="show one manifest value")
    show_parser.add_argument("--field", choices=("vendored_hub",), required=True)

    scope_parser = subparsers.add_parser(
        "scope",
        help="emit a stable TSV capability snapshot for shell consumers",
    )
    scope_parser.add_argument("--capability", required=True)
    scope_parser.add_argument(
        "--require-vendored-hub",
        action="store_true",
        help="fail unless the declared vendored hub is in the selected scope",
    )

    targets_parser = subparsers.add_parser(
        "targets", help="list local checkout roots after exact Git identity validation"
    )
    targets_parser.add_argument("--capability", required=True)
    targets_parser.add_argument(
        "--dotenv",
        type=Path,
        help="explicit dotenv file for checkout roots; exported values take precedence",
    )
    return parser


def main(argv: Iterable[str] | None = None) -> int:
    args = _parser().parse_args(list(argv) if argv is not None else None)
    try:
        manifest = load_fleet_manifest()
        if args.command == "list":
            _list_command(args, manifest)
        elif args.command == "matrix":
            _matrix_command(args, manifest)
        elif args.command == "show":
            _show_command(args, manifest)
        elif args.command == "scope":
            _scope_command(args, manifest)
        else:
            _targets_command(args, manifest)
    except FleetManifestError as exc:
        print(f"fleet manifest error: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Pure MIM owned-name export policy (MIM #669, Claw #701).

Callers own the complete mapped-record snapshot, source references, validation
and publication. SUPPRESS is an export decision; it neither rejects a source
synonym nor establishes that two records denote the same substance.
"""

from __future__ import annotations

import csv
import io
import json
from collections.abc import Iterable, Mapping
from dataclasses import dataclass

POLICY_VERSION = "owned-name-policy-v1"
SIDECAR_COLUMNS = (
    "subject_id", "token_key", "token", "owner_subject_ids", "disposition",
    "input_surfaces", "source_refs", "evidence_refs",
)


@dataclass(frozen=True)
class AliasCandidate:
    """One pipe-free `other` token and its caller-supplied provenance."""

    text: str
    input_surface: str
    source_refs: tuple[str, ...] = ()
    evidence_refs: tuple[str, ...] = ()


@dataclass(frozen=True)
class Suppression:
    """One observed exclusion; rendering combines repeated pair encounters."""

    subject_id: str
    token: str
    owner_subject_ids: frozenset[str]
    input_surface: str
    source_refs: tuple[str, ...]
    evidence_refs: tuple[str, ...]


def _subject(value: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError("A nonempty subject ID is required")
    return value.strip()


def _token(value: str) -> str:
    if not isinstance(value, str):
        raise ValueError("Alias token must be a string")
    if "|" in value:
        raise ValueError("Split pipe-delimited aliases into attributed tokens first")
    return value.strip()


def build_owner_index(
    records: Mapping[str, Mapping[str, object]],
) -> dict[str, frozenset[str]]:
    """Mirror native Rule K ownership without reads, caches or target filtering.

    Subject keys are the caller's forward-escaped filenames. An explicit
    representative takes precedence even when empty, null or unresolved.
    Only an absent representative permits the legacy identifier fallback.
    """
    entries = tuple(records.items())
    for subject, data in entries:
        if _subject(subject) != subject:
            raise ValueError("Snapshot subject IDs must already be stripped")
        if not isinstance(data, Mapping):
            raise ValueError(f"Record {subject} is not a mapping")

    def rejected(data: Mapping[str, object]) -> bool:
        return str(data.get("mapping_status") or "").strip().upper() == "REJECTED"

    live_by_identifier: dict[str, set[str]] = {}
    for subject, data in entries:
        identifier = str(data.get("identifier") or "").strip()
        if identifier and not rejected(data):
            live_by_identifier.setdefault(identifier, set()).add(subject)

    owners: dict[str, set[str]] = {}
    for subject, data in entries:
        term = str(data.get("preferred_term") or "").strip()
        if not term:
            continue
        if rejected(data):
            target = data.get("representative") if "representative" in data else data.get("identifier")
            credited = live_by_identifier.get(str(target or "").strip())
            owners.setdefault(term.casefold(), set()).update(credited or {subject})
        else:
            owners.setdefault(term.casefold(), set()).add(subject)
    return {term: frozenset(subjects) for term, subjects in owners.items()}


def filter_owned_aliases(
    subject_id: str,
    candidates: Iterable[AliasCandidate],
    owners: Mapping[str, frozenset[str]],
) -> tuple[tuple[AliasCandidate, ...], tuple[Suppression, ...]]:
    """Keep unowned or subject-owned tokens; preserve allowed input order.

    Upstream synonym eligibility and downstream deduplication/capping remain
    caller responsibilities. Blank candidates are left for that existing path,
    and cannot create an exclusion. No canonical baseline exempts a collision.
    """
    subject = _subject(subject_id)
    kept: list[AliasCandidate] = []
    suppressed: list[Suppression] = []
    for candidate in candidates:
        token = _token(candidate.text)
        holders = owners.get(token.casefold()) if token else None
        if not holders or subject in holders:
            kept.append(candidate)
            continue
        suppressed.append(Suppression(
            subject, token, frozenset(holders), candidate.input_surface,
            candidate.source_refs, candidate.evidence_refs,
        ))
    return tuple(kept), tuple(suppressed)


def _references(values: tuple[str, ...], field: str) -> set[str]:
    if not isinstance(values, tuple) or not values:
        raise ValueError(f"Suppression requires nonempty {field}")
    if any(not isinstance(value, str) or not value.strip() for value in values):
        raise ValueError(f"Suppression {field} must contain nonempty strings")
    return set(values)


def render_suppressed_aliases(events: Iterable[Suppression]) -> bytes:
    """Render deterministic, provenance-complete, one-row-per-pair TSV bytes.

    Owners, origins and references are unions across encounters. The displayed
    spelling is the minimum observed trimmed spelling, never an invented label.
    The manifest that binds these references and bytes belongs to the caller.
    """
    grouped: dict[tuple[str, str], dict[str, set[str]]] = {}
    for event in events:
        subject = _subject(event.subject_id)
        token = _token(event.token)
        if not token:
            raise ValueError("Suppression requires a nonempty token")
        holders = event.owner_subject_ids
        if not isinstance(holders, frozenset) or not holders:
            raise ValueError("Suppression requires a nonempty owner set")
        if any(_subject(owner) != owner for owner in holders):
            raise ValueError("Suppression owner IDs must already be stripped")
        if subject in holders:
            raise ValueError("Cannot suppress a token credited to the subject")
        surface = event.input_surface
        if not isinstance(surface, str) or not surface.strip():
            raise ValueError("Suppression requires an input surface")
        source_refs = _references(event.source_refs, "source_refs")
        evidence_refs = _references(event.evidence_refs, "evidence_refs")
        group = grouped.setdefault((subject, token.casefold()), {
            "tokens": set(), "owner_subject_ids": set(), "input_surfaces": set(),
            "source_refs": set(), "evidence_refs": set(),
        })
        group["tokens"].add(token)
        group["owner_subject_ids"].update(holders)
        group["input_surfaces"].add(surface)
        group["source_refs"].update(source_refs)
        group["evidence_refs"].update(evidence_refs)

    out = io.StringIO(newline="")
    writer = csv.DictWriter(out, fieldnames=SIDECAR_COLUMNS,
                            delimiter="\t", lineterminator="\n")
    writer.writeheader()
    for (subject, key), group in sorted(grouped.items()):
        row = {
            "subject_id": subject, "token_key": key,
            "token": min(group["tokens"]), "disposition": "SUPPRESS",
        }
        for field in ("owner_subject_ids", "input_surfaces", "source_refs", "evidence_refs"):
            row[field] = json.dumps(sorted(group[field]), ensure_ascii=False, separators=(",", ":"))
        writer.writerow(row)
    return out.getvalue().encode("utf-8")

"""Portable, versioned validation for registry and occurrence companion claims."""

from __future__ import annotations

import csv
import hashlib
import io
import json
import re
from datetime import date
from functools import lru_cache
from importlib.resources import files
from pathlib import Path

import yaml
from jsonschema import Draft202012Validator

from .mapping_scope import (
    profile_metadata,
    read_profile_table,
    scope_profile,
    validate_scope_row,
    write_profile_table,
)
from .review_claims import validate_review_decision
from .sssom_metadata import subset_date_metadata

BUNDLE_VERSION = 1
CAPABILITIES = frozenset(
    {
        "ingredient-scope-v1",
        "owner-bound-review-v1",
        "identifier-annotations-v1",
        "ingredient-occurrences-v1",
        "catalog-products-v1",
    }
)
REQUIRED_CAPABILITIES = frozenset(
    {"ingredient-scope-v1", "owner-bound-review-v1", "identifier-annotations-v1"}
)
ANNOTATION_FIELDS = (
    "annotation_id",
    "owner_id",
    "identifier",
    "raw_identifier",
    "identifier_scope",
    "identifier_validity",
    "source_status",
    "source_currentness",
    "source_id",
    "source_version",
    "retrieved_at",
    "evidence",
    "review_status",
    "xref_eligible",
)
SCHEMA_NAME = "ingredient_bundle_v1.schema.json"
PROFILE_NAME = "ingredient_scope_v1.yaml"
HISTORICAL_STATUSES = frozenset({"SUPERSEDED", "HISTORICAL", "DEPRECATED", "WITHDRAWN"})


def canonical_json(value) -> bytes:
    """Encode a deterministic JSON value, rejecting non-finite numbers."""
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
    ).encode("utf-8")


def content_sha256(content: bytes) -> str:
    """Identify exact bytes, without trusting a caller-supplied digest."""
    return hashlib.sha256(content).hexdigest()


def stable_id(kind: str, key) -> str:
    """Identify a source claim or entity by its documented natural key."""
    return f"MIM.{kind}:" + content_sha256(canonical_json(key))


def annotation_id(payload: dict) -> str:
    """Keep source/version/status claims distinct while binding revisions separately."""
    return stable_id(
        "annotation",
        [
            payload[k]
            for k in (
                "owner_id",
                "identifier",
                "raw_identifier",
                "source_id",
                "source_status",
                "source_version",
                "retrieved_at",
            )
        ],
    )


def product_id(supplier: str, catalog_number: str) -> str:
    """A supplier/catalog specification identifies a product, never an individual lot."""
    return stable_id("product", [supplier.strip().casefold(), catalog_number.strip()])


def occurrence_id(source_id: str, source_occurrence_key: str) -> str:
    """Keep an explicitly named source occurrence stable across payload corrections."""
    return stable_id("occurrence", [source_id, source_occurrence_key])


def alternative_id(occurrence: str, group_key: str) -> str:
    """Identify an alternatives group independently of its current option payloads."""
    return stable_id("alternative", [occurrence, group_key])


def valid_cas(identifier: str) -> bool:
    """Validate normalized CAS syntax and checksum without guessing a replacement."""
    if not re.fullmatch(r"cas:[1-9][0-9]{1,6}-[0-9]{2}-[0-9]", identifier):
        return False
    digits = identifier.removeprefix("cas:").replace("-", "")
    return sum(i * int(value) for i, value in enumerate(reversed(digits[:-1]), 1)) % 10 == int(
        digits[-1]
    )


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"Duplicate bundle JSON key: {key}")
        result[key] = value
    return result


def read_json(content: bytes):
    """Read JSON without silently choosing between duplicate keys or NaN values."""

    def invalid_number(value):
        raise ValueError(f"Non-finite bundle JSON number: {value}")

    return json.loads(content, object_pairs_hook=_unique_object, parse_constant=invalid_number)


@lru_cache(maxsize=2)
def contract_resource(name: str) -> bytes:
    """Read the pinned packaged schema/profile, not a remote default."""
    if name not in {SCHEMA_NAME, PROFILE_NAME}:
        raise ValueError(f"Unknown ingredient bundle contract resource: {name}")
    return files(__package__.split(".")[0]).joinpath("profiles/" + name).read_bytes()


@lru_cache(maxsize=3)
def _validator(kind: str):
    if kind not in {"identifier", "product", "occurrence"}:
        raise ValueError(f"Unknown companion claim kind: {kind}")
    schema = read_json(contract_resource(SCHEMA_NAME))
    return Draft202012Validator({"$ref": f"#/$defs/{kind}", "$defs": schema["$defs"]})


def validate_payload(kind: str, payload: dict) -> None:
    """Validate claim shape and nonidentity rules before review or graph use."""
    canonical_json(payload)
    errors = sorted(_validator(kind).iter_errors(payload), key=lambda e: str(list(e.path)))
    if errors:
        raise ValueError(f"Invalid {kind} claim: {errors[0].message}")
    if kind == "identifier":
        if payload["annotation_id"] != annotation_id(payload):
            raise ValueError("Identifier annotation ID does not match its source/owner tuple")
        identifier = payload["identifier"]
        validity = payload["identifier_validity"]
        if identifier and (
            not re.fullmatch(r"\S+:\S+", identifier)
            or (identifier.lower().startswith("cas:") and not valid_cas(identifier))
        ):
            raise ValueError(
                "Invalid normalized identifier; preserve rejected raw evidence instead"
            )
        if validity == "VALID" and not identifier:
            raise ValueError("Valid identifier claim requires an identifier")
        if validity == "INVALID" and (identifier or not payload["raw_identifier"]):
            raise ValueError(
                "Invalid source value must stay raw; no inferred replacement identifier"
            )
        if (
            payload["source_status"].strip().upper() in HISTORICAL_STATUSES
            and payload["source_currentness"] != "HISTORICAL"
        ):
            raise ValueError("A historical source claim cannot be relabeled current")
        date.fromisoformat(payload["retrieved_at"])
        if payload["xref_eligible"] and (
            payload["review_status"] != "SUPPORTED"
            or validity != "VALID"
            or payload["source_currentness"] != "CURRENT"
            or payload["identifier_scope"] == "unknown"
        ):
            raise ValueError("Active xref requires a supported, current, valid and scoped claim")
    elif kind == "product":
        if not payload["supplier"].strip() or not payload["catalog_number"].strip():
            raise ValueError("Product specification requires a nonblank supplier and catalog key")
        if payload["product_id"] != product_id(payload["supplier"], payload["catalog_number"]):
            raise ValueError("Product ID does not match supplier/catalog specification")
    else:
        if not payload["source_occurrence_key"].strip():
            raise ValueError("Occurrence requires a nonblank source key")
        occurrence = occurrence_id(payload["source_id"], payload["source_occurrence_key"])
        if payload["occurrence_id"] != occurrence:
            raise ValueError("Occurrence ID does not match its source key")
        groups = set()
        for group in payload["alternatives"]:
            group_id = alternative_id(occurrence, group["group_key"])
            if group["alternative_group_id"] != group_id or group_id in groups:
                raise ValueError("Invalid or duplicate occurrence alternative group")
            groups.add(group_id)
            products = [member["product_id"] for member in group["members"]]
            if len(products) != len(set(products)):
                raise ValueError("Duplicate product alternative")
        if groups and payload["product_id"] is not None:
            raise ValueError("An unresolved alternative group cannot assert a selected product")


def annotation_table(rows: list[dict]) -> bytes:
    """Serialize one complete source claim per TSV row; evidence is one JSON cell."""
    stream = io.StringIO(newline="")
    writer = csv.DictWriter(
        stream, fieldnames=ANNOTATION_FIELDS, delimiter="\t", lineterminator="\n"
    )
    writer.writeheader()
    for row in sorted(rows, key=lambda item: item["annotation_id"]):
        validate_payload("identifier", row)
        encoded = dict(
            row,
            evidence=canonical_json(row["evidence"]).decode(),
            xref_eligible=str(row["xref_eligible"]).lower(),
        )
        writer.writerow(encoded)
    return stream.getvalue().encode()


def read_annotation_table(content: bytes) -> list[dict]:
    """Restore exact identifier/source/status tuples with strict column and boolean types."""
    reader = csv.DictReader(io.StringIO(content.decode()), delimiter="\t", strict=True)
    if reader.fieldnames != list(ANNOTATION_FIELDS):
        raise ValueError("Unsupported identifier-annotation columns")
    result = []
    for row in reader:
        if None in row or any(value is None for value in row.values()):
            raise ValueError("Malformed identifier-annotation row")
        if row["xref_eligible"] not in {"true", "false"}:
            raise ValueError("Annotation xref_eligible must be a TSV boolean")
        payload = dict(
            row,
            evidence=read_json(row["evidence"].encode()),
            xref_eligible=row["xref_eligible"] == "true",
        )
        validate_payload("identifier", payload)
        result.append(payload)
    if len({row["annotation_id"] for row in result}) != len(result):
        raise ValueError("Duplicate identifier annotation ID")
    return result


def safe_member(root: Path, name: str) -> Path:
    """Confine manifest members to the bundle directory, including resolved symlinks."""
    path = Path(name)
    if (
        not name
        or path.as_posix() != name
        or path.is_absolute()
        or ".." in path.parts
        or "\\" in name
    ):
        raise ValueError(f"Unsafe ingredient bundle member: {name}")
    result = root / path
    if not result.resolve().is_relative_to(root.resolve()):
        raise ValueError(f"Ingredient bundle member escapes its root: {name}")
    return result


def validate_member_hashes(
    root: Path, manifest: dict, capabilities=CAPABILITIES
) -> dict[str, bytes]:
    """Reject unsupported versions, capabilities, changed bytes and undeclared files."""
    if (
        type(manifest.get("schema_version")) is not int
        or manifest["schema_version"] != BUNDLE_VERSION
    ):
        raise ValueError("Unsupported ingredient bundle version")
    required = manifest.get("required_capabilities")
    if not isinstance(required, list) or not all(isinstance(x, str) for x in required):
        raise ValueError("Missing ingredient bundle capabilities")
    if len(set(required)) != len(required) or not REQUIRED_CAPABILITIES.issubset(required):
        raise ValueError("Required ingredient bundle capability was lost")
    if set(required) - set(capabilities):
        raise ValueError("Consumer lacks required ingredient bundle capabilities")
    members = manifest.get("members")
    if not isinstance(members, dict) or not members:
        raise ValueError("Ingredient bundle has no declared members")
    contents = {}
    for name, expected in members.items():
        if not isinstance(expected, dict) or set(expected) != {"sha256", "bytes"}:
            raise ValueError(f"Invalid bundle member declaration: {name}")
        content = safe_member(root, name).read_bytes()
        if content_sha256(content) != expected["sha256"] or len(content) != expected["bytes"]:
            raise ValueError(f"Ingredient bundle member digest/size mismatch: {name}")
        contents[name] = content
    actual = {p.relative_to(root).as_posix() for p in root.rglob("*") if p.is_file()}
    if actual != {"manifest.json", *members}:
        raise ValueError("Ingredient bundle contains missing or undeclared members")
    for name in (SCHEMA_NAME, PROFILE_NAME):
        if contents.get(name) != contract_resource(name):
            raise ValueError(f"Unsupported or modified ingredient bundle contract: {name}")
    return contents


ARTIFACTS = {
    "mappings": "ingredient_mappings.sssom.tsv",
    "identifiers": "ingredient_identifier_annotations.tsv",
    "products": "ingredient_products.json",
    "occurrences": "ingredient_occurrences.json",
}


def _owner_id(owner: str) -> str:
    stem = Path(owner).stem
    safe = re.sub(r"[^A-Za-z0-9_\-.]", lambda m: f"~{ord(m.group(0)):02X}", stem)
    if not owner.startswith("data/ingredients/") or not owner.endswith(".yaml"):
        raise ValueError("Claim owner must be an ingredient record")
    return f"MIM:{safe}"


def _base_table(content: bytes) -> tuple[dict, list[str], list[dict]]:
    """Read original source rows losslessly; only reviewed selections can be exported."""
    stream = io.StringIO(content.decode())
    header = []
    for line in stream:
        if not line.startswith("#"):
            first = line
            break
        header.append(line[1:].removeprefix(" "))
    else:
        raise ValueError("Missing original SSSOM table")
    metadata = yaml.safe_load("".join(header))
    reader = csv.DictReader(io.StringIO(first + stream.read()), delimiter="\t", strict=True)
    fields = list(reader.fieldnames or [])
    if len(fields) != len(set(fields)) or not {
        "subject_id",
        "object_id",
        "predicate_id",
        "subject_label",
    }.issubset(fields):
        raise ValueError("Invalid original SSSOM columns")
    rows = list(reader)
    if any(None in row or any(v is None for v in row.values()) for row in rows):
        raise ValueError("Malformed original SSSOM row")
    return metadata, fields, rows


def reviewed_products(review: dict, sources: dict[str, bytes]) -> tuple[dict[str, bytes], dict]:
    """Reconstruct artifacts from complete, independently owned reviewed claims.

    The original mapping review format supplies each base disposition; companion
    decisions use the same verifier and additionally bind the explicit owner path.
    A consumer trusts a pinned bundle/review revision, never a self-issued checksum.
    """
    if type(review.get("schema_version")) is not int or review["schema_version"] != BUNDLE_VERSION:
        raise ValueError("Unsupported companion review version")
    declared: dict[str, str] = {}
    for group in ("inputs", "record_inputs"):
        if not isinstance(review.get(group), dict):
            raise ValueError(f"Missing companion review {group}")
        for name, expected in review[group].items():
            if name in declared and declared[name] != expected:
                raise ValueError("Conflicting companion input hashes")
            declared[name] = expected
    for name_key, hash_key in (
        ("claims_file", "claims_sha256"),
        ("base_review", "base_review_sha256"),
    ):
        name, expected = review[name_key], review[hash_key]
        if name in declared and declared[name] != expected:
            raise ValueError("Conflicting companion control-file hash")
        declared[name] = expected
    if set(sources) != set(declared):
        raise ValueError("Bundle sources must exactly cover declared review inputs")
    for name, expected in declared.items():
        if content_sha256(sources[name]) != expected:
            raise ValueError(f"Stale companion review input: {name}")
    claims_document = read_json(sources[review["claims_file"]])
    if (
        set(claims_document) != {"schema_version", "claims"}
        or claims_document["schema_version"] != BUNDLE_VERSION
    ):
        raise ValueError("Unsupported companion claims document")
    claims = claims_document["claims"]
    if not isinstance(claims, list) or not claims:
        raise ValueError("Missing companion claims")
    base = read_json(sources[review["base_review"]])
    if (
        base.get("schema_version") != 1
        or content_sha256(sources[base["source_sssom"]]) != base["source_sha256"]
    ):
        raise ValueError("Stale original mapping review/source")
    metadata, fields, original_rows = _base_table(sources[base["source_sssom"]])
    extensions = [item["slot_name"] for item in scope_profile()["extension_definitions"]]
    if set(fields) & set(extensions):
        raise ValueError("Base source must precede scope extensions")
    metadata = profile_metadata(metadata)
    metadata["curie_map"]["sha256"] = "urn:sha256:"
    decisions = review.get("decisions", [])
    indexed = {decision.get("claim_id"): decision for decision in decisions}
    if len(indexed) != len(decisions) or len(decisions) != len(claims):
        raise ValueError("Companion review must uniquely and completely cover claims")
    proofs: dict = {}
    owners: dict[str, str] = {}
    seen: set[str] = set()
    mappings: list[dict] = []
    annotations: list[dict] = []
    products: list[dict] = []
    occurrences: list[dict] = []
    verified = {name: sources[name] for name in review["inputs"]}
    documents = {"urn:sha256:" + content_sha256(content) for content in verified.values()}
    base_decisions = {}
    for decision in base["decisions"]:
        position = decision.get("source_position")
        if (
            type(position) is not int
            or not 1 <= position <= len(original_rows)
            or position in base_decisions
        ):
            raise ValueError("Invalid original review position")
        base_decisions[position] = decision
    original_index = {
        content_sha256(canonical_json(row)): i for i, row in enumerate(original_rows, 1)
    }
    for claim in claims:
        if set(claim) != {"claim_id", "kind", "owner_record", "payload"}:
            raise ValueError("Unsupported companion claim envelope")
        claim_id, kind, owner, payload = (
            claim[key] for key in ("claim_id", "kind", "owner_record", "payload")
        )
        if claim_id in seen or claim_id not in indexed or owner not in review["record_inputs"]:
            raise ValueError("Duplicate, unreviewed or unowned companion claim")
        seen.add(claim_id)
        owner_id = _owner_id(owner)
        record = yaml.safe_load(sources[owner])
        if not isinstance(record, dict) or record.get("mapping_status") != "MAPPED":
            raise ValueError("Claim owner is not a mapped ingredient record")
        owners[owner_id] = owner
        decision = indexed[claim_id]
        validate_review_decision(
            decision,
            claim,
            owner,
            review["record_inputs"][owner],
            verified,
            proofs,
            require_owner_path=True,
        )
        if kind == "mapping":
            if claim_id != stable_id(
                "mapping", [payload[key] for key in ("subject_id", "predicate_id", "object_id")]
            ):
                raise ValueError("Mapping claim ID differs from its scoped endpoints")
            if (
                set(payload) != set(fields + extensions)
                or payload["subject_id"] != owner_id
                or payload["subject_label"] != record.get("preferred_term")
            ):
                raise ValueError("Scoped mapping does not describe its independent source owner")
            original = {key: payload[key] for key in fields}
            position = original_index.get(content_sha256(canonical_json(original)))
            base_decision = base_decisions.get(position) if position is not None else None
            if not base_decision or base_decision["disposition"] != "SUPPORTED":
                raise ValueError(
                    "Scoped mapping must retain an existing supported complete source row"
                )
            evidence = base_decision["review_evidence"]
            if (
                evidence not in base["inputs"]
                or content_sha256(sources[evidence]) != base["inputs"][evidence]
            ):
                raise ValueError("Original mapping review evidence is missing or changed")
            if base["record_inputs"].get(owner) != review["record_inputs"][owner]:
                raise ValueError("Scoped mapping owner changed since base review")
            validate_review_decision(
                base_decision, original, owner, review["record_inputs"][owner], verified, proofs
            )
            if (
                decision["disposition"] != "SUPPORTED"
                or payload["ext_scope_review_status"] != "SUPPORTED"
            ):
                raise ValueError("Exported scoped mapping requires supported scope review")
            validate_scope_row(payload, metadata)
            evidence_id = payload["ext_scope_evidence"].replace("sha256:", "urn:sha256:", 1)
            if evidence_id not in documents:
                raise ValueError("Scope evidence document is not bundled")
            mappings.append(payload)
        else:
            validate_payload(kind, payload)
            owner_field = "owner_id" if kind == "identifier" else "ingredient_id"
            if payload[owner_field] != owner_id and not (
                kind == "identifier" and payload[owner_field].startswith("MIM.product:")
            ):
                raise ValueError("Companion payload belongs to another ingredient")
            identity_field = {
                "identifier": "annotation_id",
                "product": "product_id",
                "occurrence": "occurrence_id",
            }[kind]
            if claim_id != payload[identity_field]:
                raise ValueError("Companion claim ID differs from its payload identity")
            if payload["review_status"] != decision["disposition"]:
                raise ValueError("Companion claim status disagrees with reviewed disposition")
            if any(item["document_id"] not in documents for item in payload["evidence"]):
                raise ValueError("Companion evidence document is not bundled")
            target = {"identifier": annotations, "product": products, "occurrence": occurrences}[
                kind
            ]
            target.append(payload)
    if set(review["record_inputs"]) != set(owners.values()):
        raise ValueError("Companion record inputs include unrelated owners")
    identities: dict[str, str] = {}
    scoped_owners: dict[str, str] = {}
    for row in mappings:
        subject = row["subject_id"]
        scope = row["ext_subject_scope"].removeprefix("mimscope:")
        if subject in scoped_owners and scoped_owners[subject] != scope:
            raise ValueError("Conflicting scopes require distinct source concepts")
        scoped_owners[subject] = scope
        if validate_scope_row(row, metadata):
            if subject in identities and identities[subject] != row["object_id"]:
                raise ValueError(
                    "Competing authorized identities require source-context resolution"
                )
            identities[subject] = row["object_id"]
    product_map = {row["product_id"]: row for row in products}
    if len(product_map) != len(products) or len({r["occurrence_id"] for r in occurrences}) != len(
        occurrences
    ):
        raise ValueError("Duplicate product or occurrence identity")
    if len({r["annotation_id"] for r in annotations}) != len(annotations):
        raise ValueError("Duplicate registry claim identity")
    for payload in products + occurrences:
        if payload["ingredient_id"] not in scoped_owners:
            raise ValueError("Product/occurrence ingredient lacks a reviewed scoped mapping")
    for claim in claims:
        payload = claim["payload"]
        if claim["kind"] == "identifier":
            identifier_owner = payload["owner_id"]
            if identifier_owner.startswith("MIM.product:"):
                if identifier_owner not in product_map or product_map[identifier_owner][
                    "ingredient_id"
                ] != _owner_id(claim["owner_record"]):
                    raise ValueError("Registry product claim has the wrong ingredient owner")
            elif identifier_owner not in scoped_owners:
                raise ValueError("Registry owner lacks a reviewed scoped mapping")
            if (
                identifier_owner in product_map
                and payload["xref_eligible"]
                and product_map[identifier_owner]["review_status"] != "SUPPORTED"
            ):
                raise ValueError("Active registry xref refers to a withheld product")
            # Specific identifier claims may be retained on a broader owner as
            # evidence, but cannot become active xrefs of that owner.
            expected_scope = scoped_owners.get(identifier_owner)
            if (
                payload["xref_eligible"]
                and expected_scope is not None
                and payload["identifier_scope"] != expected_scope
            ):
                raise ValueError("Active registry annotation scope differs from its owner")
    for occurrence in occurrences:
        references = [occurrence["product_id"]] if occurrence["product_id"] else []
        references += [
            member["product_id"]
            for group in occurrence["alternatives"]
            for member in group["members"]
        ]
        for product in references:
            if (
                product not in product_map
                or product_map[product]["ingredient_id"] != occurrence["ingredient_id"]
            ):
                raise ValueError("Occurrence refers to a missing or differently owned product")
            if (
                occurrence["review_status"] == "SUPPORTED"
                and product_map[product]["review_status"] != "SUPPORTED"
            ):
                raise ValueError("Supported occurrence refers to a withheld product")
    mappings.sort(key=lambda r: (r["subject_id"], r["predicate_id"], r["object_id"]))
    metadata = subset_date_metadata(metadata, mappings)
    products.sort(key=lambda r: r["product_id"])
    occurrences.sort(key=lambda r: r["occurrence_id"])
    artifacts = {
        ARTIFACTS["mappings"]: write_profile_table(metadata, fields + extensions, mappings),
        ARTIFACTS["identifiers"]: annotation_table(annotations),
    }
    if products:
        artifacts[ARTIFACTS["products"]] = canonical_json(products) + b"\n"
    if occurrences:
        artifacts[ARTIFACTS["occurrences"]] = canonical_json(occurrences) + b"\n"
    return artifacts, {
        "metadata": metadata,
        "mappings": mappings,
        "identifiers": annotations,
        "products": products,
        "occurrences": occurrences,
        "identities": identities,
        "owners": owners,
    }


def validate_bundle(
    root: Path, *, expected_manifest_sha256: str | None = None, capabilities=CAPABILITIES
) -> dict:
    """Replay reviews and every projection before any consumer builds its indexes."""
    manifest_bytes = (root / "manifest.json").read_bytes()
    fingerprint = content_sha256(manifest_bytes)
    if expected_manifest_sha256 is not None and fingerprint != expected_manifest_sha256:
        raise ValueError("Ingredient bundle manifest does not match its activation pin")
    manifest = read_json(manifest_bytes)
    contents = validate_member_hashes(root, manifest, capabilities)
    if manifest.get("review") != "review.json" or manifest.get("source_root") != "sources":
        raise ValueError("Unsupported bundle review layout")
    sources = {
        name.removeprefix("sources/"): value
        for name, value in contents.items()
        if name.startswith("sources/")
    }
    expected, loaded = reviewed_products(read_json(contents["review.json"]), sources)
    review = read_json(contents["review.json"])
    provenance = manifest.get("provenance", {})
    if (
        manifest.get("cohort") != sorted(loaded["owners"])
        or manifest.get("coverage") != "reviewed_scoped_cohort"
        or manifest.get("legacy_compatibility") != "separate_explicit_input_only"
        or provenance.get("review_sha256") != content_sha256(contents["review.json"])
        or provenance.get("base_review_sha256") != review["base_review_sha256"]
    ):
        raise ValueError("Bundle provenance or cohort differs from reviewed inputs")
    declared = {key: name if name in expected else None for key, name in ARTIFACTS.items()}
    if manifest.get("artifacts") != declared:
        raise ValueError("Missing or mismatched explicit bundle artifacts")
    required = set(REQUIRED_CAPABILITIES)
    for key, capability in (
        ("products", "catalog-products-v1"),
        ("occurrences", "ingredient-occurrences-v1"),
    ):
        if declared[key]:
            required.add(capability)
    if set(manifest["required_capabilities"]) != required:
        raise ValueError("Artifact capabilities disagree with bundle requirements")
    for name, value in expected.items():
        if contents.get(name) != value:
            raise ValueError(f"Bundle artifact differs from reviewed reconstruction: {name}")
    allowed = {
        "review.json",
        PROFILE_NAME,
        SCHEMA_NAME,
        *expected,
        *("sources/" + name for name in sources),
    }
    if set(contents) != allowed:
        raise ValueError("Bundle includes unexpected artifacts")
    # Exercise the transport reader, including required-profile enforcement.
    read_profile_table(contents[ARTIFACTS["mappings"]])
    read_annotation_table(contents[ARTIFACTS["identifiers"]])
    loaded.update(manifest=manifest, fingerprint=fingerprint)
    return loaded

"""Export an evidence-bound, reviewed SSSOM partition without KGX (#729).

Every current source row needs one explicit SUPPORTED or WITHHOLD decision.
Validation regenerates the expected partition from source and reviewed evidence;
updating an output checksum cannot legitimize a changed row or disposition.
"""

from __future__ import annotations

import argparse
import csv
import hashlib
import io
import json
import math
import re
import shutil
import tempfile
from collections import defaultdict
from pathlib import Path

import yaml

from mediaingredientmech.curie import mim_curie_for_stem
from mediaingredientmech.review_claims import validate_review_decision
from mediaingredientmech.sssom_metadata import subset_date_metadata
from mediaingredientmech.synonym_policy import is_resolving_synonym_text

PRODUCTS = (
    "ingredient_mappings.sssom.tsv",
    "withheld_mappings.sssom.tsv",
    "mapping-dispositions.tsv",
)
DISPOSITION_FIELDS = (
    "source_position",
    "row_sha256",
    "subject_id",
    "predicate_id",
    "object_id",
    "owner_record",
    "owner_record_sha256",
    "disposition",
    "review_reason",
    "review_evidence",
    "evidence_key",
)


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def row_sha256(row: dict) -> str:
    return hashlib.sha256(
        json.dumps(row, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()
    ).hexdigest()


payload_sha = row_sha256


def _unique_object(pairs: list) -> dict:
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"Duplicate JSON key: {key}")
        result[key] = value
    return result


def _json(path: Path) -> dict:
    return _json_bytes(path.read_bytes(), str(path))


def _json_bytes(content: bytes, name: str) -> dict:
    data = json.loads(content, object_pairs_hook=_unique_object)
    if not isinstance(data, dict):
        raise ValueError(f"Expected JSON object: {name}")
    return data


def _relative(root: Path, value: str) -> Path:
    path = root / value
    if (
        Path(value).is_absolute()
        or ".." in Path(value).parts
        or not path.resolve().is_relative_to(root.resolve())
    ):
        raise ValueError(f"Evidence/source path must stay within root: {value}")
    return path


def read_sssom(path: Path, *, content: bytes | None = None) -> tuple[dict, list[str], list[dict]]:
    lines = (path.read_bytes() if content is None else content).decode().splitlines(keepends=True)
    end = 0
    while end < len(lines) and lines[end].startswith("#"):
        end += 1
    metadata = yaml.safe_load("".join(line[1:].removeprefix(" ") for line in lines[:end]))
    if (
        not isinstance(metadata, dict)
        or not metadata.get("mapping_set_id")
        or metadata.get("predicate_semantics") != "skos"
    ):
        raise ValueError("SSSOM needs mapping_set_id and predicate_semantics: skos")
    reader = csv.DictReader(io.StringIO("".join(lines[end:])), delimiter="\t", strict=True)
    fields = list(reader.fieldnames or [])
    required = {"subject_id", "subject_label", "predicate_id", "object_id", "object_label", "other"}
    if len(fields) != len(set(fields)) or not required.issubset(fields):
        raise ValueError("Invalid SSSOM columns")
    rows = list(reader)
    if any(None in row or any(value is None for value in row.values()) for row in rows):
        raise ValueError("Malformed SSSOM row width")
    for row in rows:
        confidence = row.get("confidence", "").strip()
        if confidence:
            try:
                finite = math.isfinite(float(confidence))
            except ValueError as exc:
                raise ValueError("SSSOM confidence must be numeric") from exc
            if not finite:
                raise ValueError("SSSOM confidence must be finite")
    return metadata, fields, rows


def _owners(
    root: Path, rows: list[dict], verified_records: dict | None = None
) -> tuple[list[str], dict]:
    labels, subjects = defaultdict(set), defaultdict(set)
    records = {}
    for path in sorted((root / "data/ingredients").rglob("*.yaml")):
        owner = path.relative_to(root).as_posix()
        content = (verified_records or {}).get(owner)
        record = yaml.safe_load(path.read_bytes() if content is None else content)
        if not isinstance(record, dict) or record.get("mapping_status") != "MAPPED":
            continue
        records[owner] = record
        labels[record["preferred_term"]].add(owner)
        subjects[mim_curie_for_stem(path.stem)].add(owner)
    owners = []
    for row in rows:
        by_label = labels[row["subject_label"]]
        by_subject = subjects[row["subject_id"]]
        candidates = by_label & by_subject
        if not row["subject_id"].startswith("MIM:") or len(candidates) != 1:
            raise ValueError(f"No unique independent owner for {row['subject_id']}")
        owners.append(next(iter(candidates)))
    return owners, records


def _safe_synonyms(row: dict, record: dict) -> None:
    rejected = {
        str(synonym.get("synonym_text", "")).strip().casefold()
        for synonym in record.get("synonyms") or []
        if synonym.get("synonym_type") == "REJECTED_LABEL"
    }
    tokens = [token.strip() for token in row.get("other", "").split("|") if token.strip()]
    if any(
        not is_resolving_synonym_text(token) or token.casefold() in rejected for token in tokens
    ):
        raise ValueError(f"Non-resolving/rejected synonym in supported row: {row['subject_id']}")


def _safe_identifiers(row: dict) -> None:
    """Check active CAS identities and annotations without inferring chemical identity."""
    for field in ("subject_id", "object_id", "other", "xref"):
        for value in row.get(field, "").split("|"):
            token = value.strip()
            if token.lower().startswith("cas:"):
                number = token.split(":", 1)[1]
            elif re.fullmatch(r"\d+-\d+-\d+", token):
                number = token
            else:
                continue
            if not re.fullmatch(r"[1-9][0-9]{1,6}-[0-9]{2}-[0-9]", number):
                raise ValueError(f"Invalid CAS identifier in supported {field}: {token}")
            digits = number.replace("-", "")
            check = sum(weight * int(digit) for weight, digit in enumerate(digits[-2::-1], 1)) % 10
            if check != int(digits[-1]):
                raise ValueError(f"Invalid CAS check digit in supported {field}: {token}")


def load_review(root: Path, review_path: Path) -> dict:
    root = root.resolve()
    review_path = review_path if review_path.is_absolute() else root / review_path
    review_bytes = review_path.read_bytes()
    review_sha = hashlib.sha256(review_bytes).hexdigest()
    snapshots = {review_path: review_sha}
    review = _json_bytes(review_bytes, str(review_path))
    if review.get("schema_version") != 1:
        raise ValueError("Unsupported review schema")
    source = _relative(root, review["source_sssom"])
    source_bytes = source.read_bytes()
    if hashlib.sha256(source_bytes).hexdigest() != review["source_sha256"]:
        raise ValueError("Stale source SSSOM hash")
    snapshots[source] = review["source_sha256"]
    verified = {}
    for group in ("inputs", "record_inputs"):
        if not isinstance(review.get(group), dict):
            raise ValueError(f"Missing {group}")
        for name, expected in review[group].items():
            path = _relative(root, name)
            content = path.read_bytes()
            if hashlib.sha256(content).hexdigest() != expected:
                raise ValueError(f"Stale {group} hash: {name}")
            if path in snapshots and snapshots[path] != expected:
                raise ValueError(f"Conflicting input hashes: {name}")
            verified[name] = content
            snapshots[path] = expected
    metadata, fields, rows = read_sssom(source, content=source_bytes)
    owners, records = _owners(root, rows, verified)
    if set(review["record_inputs"]) != set(owners):
        raise ValueError("record_inputs must exactly cover independently resolved owners")
    decisions = review.get("decisions")
    if not isinstance(decisions, list) or len(decisions) != len(rows):
        raise ValueError("Review decisions must completely cover source rows")
    indexed: dict = {}
    proofs: dict = {}
    evidence_inputs = {name: verified[name] for name in review["inputs"]}
    for decision in decisions:
        position = decision.get("source_position")
        if type(position) is not int or not 1 <= position <= len(rows) or position in indexed:
            raise ValueError("Invalid/duplicate review source position")
        row, owner = rows[position - 1], owners[position - 1]
        validate_review_decision(
            decision,
            row,
            owner,
            review["record_inputs"][owner],
            evidence_inputs,
            proofs,
        )
        if decision["disposition"] == "SUPPORTED":
            _safe_synonyms(row, records[owner])
            _safe_identifiers(row)
        indexed[position] = decision
    selected = [
        rows[i - 1] for i, decision in indexed.items() if decision["disposition"] == "SUPPORTED"
    ]
    identities = {
        (row["subject_id"], row["object_id"])
        for row in selected
        if row["predicate_id"] == "skos:exactMatch"
    }
    for row in selected:
        if row["predicate_id"] in {"skos:narrowMatch", "skos:broadMatch"}:
            slug = row["subject_id"].removeprefix("MIM:").lower()
            if not any(
                (row["subject_id"], f"kgmicrobe.{kind}:{slug}") in identities
                for kind in ("ingredient", "compound")
            ):
                raise ValueError(
                    f"Supported asymmetric mapping lacks registry identity sibling (Rule B1): {row['subject_id']}"
                )
    loaded = {
        "review": review,
        "review_path": review_path,
        "metadata": metadata,
        "fields": fields,
        "rows": rows,
        "decisions": [indexed[i] for i in range(1, len(rows) + 1)],
        "review_sha256": review_sha,
        "input_snapshot": snapshots,
    }
    _check_snapshot(loaded)
    return loaded


def _check_snapshot(loaded: dict) -> None:
    for path, expected in loaded["input_snapshot"].items():
        if digest(path) != expected:
            raise ValueError(f"Input changed during review/export: {path}")


def _tsv(fields, rows) -> bytes:
    stream = io.StringIO(newline="")
    writer = csv.DictWriter(stream, fieldnames=fields, delimiter="\t", lineterminator="\n")
    writer.writeheader()
    writer.writerows(rows)
    return stream.getvalue().encode()


def expected_products(root: Path, review_path: Path) -> tuple[dict[str, bytes], dict]:
    return _products(load_review(root, review_path))


def _products(loaded: dict) -> tuple[dict[str, bytes], dict]:
    review, rows, decisions = loaded["review"], loaded["rows"], loaded["decisions"]
    products, counts, identifiers = {}, {}, {}
    for disposition, filename, suffix in (
        ("SUPPORTED", PRODUCTS[0], "reviewed-supported"),
        ("WITHHOLD", PRODUCTS[1], "withheld-backlog"),
    ):
        selected = [
            row
            for row, decision in zip(rows, decisions, strict=True)
            if decision["disposition"] == disposition
        ]
        metadata = subset_date_metadata(loaded["metadata"], selected)
        metadata["mapping_set_id"] = str(metadata["mapping_set_id"]).rstrip("/") + "/" + suffix
        metadata["mapping_set_description"] = (
            "Evidence-reviewed supported subset of MediaIngredientMech mappings."
            if disposition == "SUPPORTED"
            else "Withheld MediaIngredientMech mapping backlog. These rows are preserved for review and are not approved for use as supported mappings."
        )
        header = "".join(
            "# " + line + "\n"
            for line in yaml.safe_dump(
                metadata, sort_keys=False, allow_unicode=True, width=100000
            ).splitlines()
        )
        products[filename] = header.encode() + _tsv(loaded["fields"], selected)
        counts[disposition.lower()] = len(selected)
        identifiers[disposition.lower()] = metadata["mapping_set_id"]
    disposition_rows = []
    for row, decision in zip(rows, decisions, strict=True):
        item = dict(decision)
        item.update({field: row[field] for field in ("subject_id", "predicate_id", "object_id")})
        item["owner_record_sha256"] = review["record_inputs"][decision["owner_record"]]
        disposition_rows.append({field: item[field] for field in DISPOSITION_FIELDS})
    products[PRODUCTS[2]] = _tsv(DISPOSITION_FIELDS, disposition_rows)
    manifest = {
        "schema_version": 1,
        "scope": "MIM-only reviewed SSSOM; no KGX dependency",
        "semantic_status": "PASS_SUPPORTED_SUBSET",
        "source_sssom": review["source_sssom"],
        "source_sha256": review["source_sha256"],
        "review_sha256": loaded["review_sha256"],
        "counts": {"source": len(rows), **counts},
        "mapping_set_ids": identifiers,
        "files": {name: hashlib.sha256(content).hexdigest() for name, content in products.items()},
    }
    products["manifest.json"] = (json.dumps(manifest, sort_keys=True, indent=2) + "\n").encode()
    return products, manifest


def validate_reviewed(root: Path, review_path: Path, output: Path) -> dict:
    loaded = load_review(root, review_path)
    products, manifest = _products(loaded)
    if {path.name for path in output.iterdir()} != set(products):
        raise ValueError("Unexpected or missing output artifact")
    for name, content in products.items():
        if not (output / name).is_file() or (output / name).read_bytes() != content:
            raise ValueError(f"Output differs from source/evidence-derived expectation: {name}")
    _check_snapshot(loaded)
    return manifest


def export_reviewed(root: Path, review_path: Path, output: Path) -> dict:
    loaded = load_review(root, review_path)
    products, _ = _products(loaded)
    protected = {
        loaded["review_path"].resolve(),
        (root / loaded["review"]["source_sssom"]).resolve(),
    }
    protected.update(
        (root / path).resolve()
        for group in ("inputs", "record_inputs")
        for path in loaded["review"][group]
    )
    if any((output / name).resolve() in protected for name in products):
        raise ValueError("Output must not overwrite source or evidence")
    if output.is_symlink():
        raise ValueError("Output directory must not be a symlink")
    if output.exists() and any(path.name not in products for path in output.iterdir()):
        raise ValueError("Output directory contains unrelated files")
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix=f".{output.name}-", dir=output.parent) as temporary:
        stage, backup = Path(temporary) / "new", Path(temporary) / "previous"
        stage.mkdir()
        for name, content in products.items():
            (stage / name).write_bytes(content)
        manifest = validate_reviewed(root, review_path, stage)
        _check_snapshot(loaded)
        if output.exists():
            output.rename(backup)
        try:
            stage.rename(output)
            _check_snapshot(loaded)
        except BaseException:
            if output.exists():
                shutil.rmtree(output)
            if backup.exists():
                backup.rename(output)
            raise
    return manifest


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path.cwd())
    parser.add_argument("--review", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--validate-only", action="store_true")
    args = parser.parse_args()
    action = validate_reviewed if args.validate_only else export_reviewed
    print(json.dumps(action(args.root, args.review, args.output), sort_keys=True, indent=2))


if __name__ == "__main__":
    main()

"""Versioned ingredient scope contract, independent of identifier preference."""

from __future__ import annotations

import csv
import io
from copy import deepcopy
from functools import lru_cache
from importlib.resources import files
from urllib.parse import urlsplit

import yaml

PROFILE_ID = "https://w3id.org/mediaingredientmech/sssom/ingredient-scope/v1"
PROFILE_CURIE = "mimprofile:ingredient-scope/v1"


@lru_cache(maxsize=1)
def _profile() -> dict:
    profile = yaml.safe_load(
        files(__package__.split(".")[0])
        .joinpath("profiles/ingredient_scope_v1.yaml")
        .read_text(encoding="utf-8")
    )
    if not isinstance(profile, dict):
        raise ValueError("Scope profile must be a mapping")
    return profile


def scope_profile() -> dict:
    """Return the public, serializable profile without exposing cached mutable state."""
    return deepcopy(_profile())


def profile_metadata(metadata: dict, *, default_profile: bool = True) -> dict:
    """Declare extension meanings, rejecting conflicting prefix or slot definitions."""
    result = deepcopy(metadata)
    prefixes = result.setdefault("curie_map", {})
    for prefix, iri in _profile()["curie_map"].items():
        if prefix in prefixes and prefixes[prefix] != iri:
            raise ValueError(f"Conflicting scope profile prefix: {prefix}")
        prefixes[prefix] = iri
    definitions = result.setdefault("extension_definitions", [])
    if not isinstance(definitions, list):
        raise ValueError("extension_definitions must be a list")
    indexed = {}
    properties = set()
    for definition in definitions:
        slot = definition.get("slot_name")
        if not slot or slot in indexed:
            raise ValueError("Duplicate or unnamed SSSOM extension definition")
        indexed[slot] = definition
        if definition.get("property"):
            prop = _expand(definition["property"], prefixes)
            if prop in properties:
                raise ValueError(f"Duplicate SSSOM extension property: {prop}")
            properties.add(prop)
    for definition in _profile()["extension_definitions"]:
        slot = definition["slot_name"]
        if slot in indexed:
            if indexed[slot] != definition:
                raise ValueError(f"Conflicting scope extension definition: {slot}")
        else:
            prop = _expand(definition["property"], prefixes)
            if prop in properties:
                raise ValueError(f"Duplicate SSSOM extension property: {prop}")
            properties.add(prop)
            definitions.append(deepcopy(definition))
    if default_profile:
        if _expand(result.get("ext_scope_profile", PROFILE_CURIE), prefixes) != PROFILE_ID:
            raise ValueError("Unsupported ingredient scope profile")
        result["ext_scope_profile"] = PROFILE_CURIE
    return result


def _expand(value: str, prefixes: dict) -> str:
    if not isinstance(value, str) or not value or any(char.isspace() for char in value):
        raise ValueError(f"Expected scope IRI or declared CURIE: {value!r}")
    parsed = urlsplit(value)
    if parsed.scheme in {"http", "https"} and parsed.netloc:
        return value
    if value.startswith("urn:") and len(value.split(":")) > 2 and value.split(":", 2)[2]:
        return value
    prefix, sep, local = value.partition(":")
    if sep and local and prefix in prefixes:
        base = prefixes[prefix]
        if not isinstance(base, str):
            raise ValueError(f"CURIE prefix must resolve to a string: {prefix}")
        return base + local
    raise ValueError(f"Undeclared scope/evidence CURIE: {value}")


def validate_scope_row(row: dict, metadata: dict) -> bool | None:
    """
    Validate scope declarations and return identity permission, or None for legacy.

    SUPPORTED and authorization are asserted review outcomes. A release consumer
    must additionally verify the bundle's content/owner-bound review evidence.
    Equal scope vocabulary values alone never establish chemical equivalence.
    """
    fields = {item["slot_name"] for item in _profile()["extension_definitions"]}
    prefixes = metadata.get("curie_map", {})
    declared_value = metadata.get("ext_scope_profile", "")
    explicit_value = row.get("ext_scope_profile", "")
    declared = _expand(declared_value, prefixes) if declared_value else ""
    explicit = _expand(explicit_value, prefixes) if explicit_value else ""
    if declared and explicit and declared != explicit:
        raise ValueError("Conflicting row and mapping-set scope profiles")
    profile = explicit or declared
    if not profile:
        if any(row.get(field) for field in fields - {"ext_scope_profile"}):
            raise ValueError("Scope fields require a declared scope profile")
        return None
    if profile != PROFILE_ID:
        raise ValueError(f"Unsupported ingredient scope profile: {profile}")
    expected = profile_metadata(metadata, default_profile=False)
    if expected.get("extension_definitions") != metadata.get("extension_definitions"):
        raise ValueError("Scope extension definitions are missing or inconsistent")
    if any(prefixes.get(key) != value for key, value in _profile()["curie_map"].items()):
        raise ValueError("Scope profile prefixes are missing or inconsistent")

    scopes = []
    compositions = []
    for side in ("subject", "object"):
        scope = _expand(row.get(f"ext_{side}_scope", ""), prefixes)
        allowed = {prefixes["mimscope"] + value for value in _profile()["scope_values"]}
        if scope not in allowed:
            raise ValueError(f"Unknown {side} scope: {scope}")
        scopes.append(scope)
        composition = _expand(row.get(f"ext_{side}_composition", ""), prefixes)
        allowed = {prefixes["mimscope"] + value for value in _profile()["composition_values"]}
        if composition not in allowed:
            raise ValueError(f"Unknown {side} composition: {composition}")
        compositions.append(composition)
    status = row.get("ext_scope_review_status")
    if status not in _profile()["review_status_values"]:
        raise ValueError(f"Invalid scope review status: {status}")
    authorized = row.get("ext_identity_authorized")
    if authorized not in {"true", "false"}:
        raise ValueError("ext_identity_authorized must be TSV boolean true or false")
    evidence = row.get("ext_scope_evidence", "")
    if evidence:
        _expand(evidence, prefixes)
    if status in {"SUPPORTED", "WITHHOLD"} and not evidence:
        raise ValueError("Reviewed scope requires explicit evidence")
    predicate = row.get("predicate_id", "")
    if predicate not in _profile()["identity_predicates"] + _profile()["nonidentity_predicates"]:
        raise ValueError(f"Unsupported profiled mapping predicate: {predicate}")
    if authorized == "true":
        if (
            row.get("predicate_modifier", "").strip()
            or not row.get("subject_id", "").strip()
            or not row.get("object_id", "").strip()
            or status != "SUPPORTED"
            or predicate not in _profile()["identity_predicates"]
            or scopes[0] != scopes[1]
            or scopes[0] == prefixes["mimscope"] + "unknown"
            or compositions[0] != compositions[1]
        ):
            raise ValueError(
                "Identity authorization requires supported matching scope/composition and exactMatch"
            )
        return True
    return False


class _UniqueLoader(yaml.SafeLoader):
    """Reject duplicate metadata keys instead of accepting the last authorization."""


def _unique_mapping(loader, node):
    pairs = loader.construct_pairs(node, deep=True)
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"Duplicate SSSOM metadata key: {key}")
        result[key] = value
    return result


_UniqueLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, _unique_mapping)


def _load_yaml(content: str):
    loader = _UniqueLoader(content)
    try:
        return loader.get_single_data()
    finally:
        loader.dispose()


def read_scope_metadata(header: str) -> dict:
    """Parse declared scope metadata without accepting duplicate YAML keys."""
    if "ext_scope_profile" not in header:
        return {}
    metadata = _load_yaml(header)
    if not isinstance(metadata, dict):
        raise ValueError("Scope profile metadata must be a mapping")
    return metadata


def _compact(value: str, prefixes: dict) -> str:
    expanded = _expand(value, prefixes)
    if value.partition(":")[0] in prefixes:
        return value
    choices = [
        (len(base), prefix, expanded[len(base) :])
        for prefix, base in prefixes.items()
        if expanded.startswith(base) and expanded[len(base) :]
    ]
    if not choices:
        raise ValueError(f"SSSOM/TSV requires a declared CURIE prefix for {value}")
    _, prefix, local = max(choices)
    return f"{prefix}:{local}"


def _validate_profile_table(metadata: dict, fields: list[str], rows: list[dict]) -> None:
    if (
        not isinstance(metadata, dict)
        or not metadata.get("mapping_set_id")
        or not metadata.get("license")
    ):
        raise ValueError("Profiled SSSOM requires mapping_set_id and license")
    required = {"subject_id", "predicate_id", "object_id", "mapping_justification"}
    if len(fields) != len(set(fields)) or not required.issubset(fields):
        raise ValueError("Invalid profiled SSSOM columns")
    if not rows:
        raise ValueError("Profiled SSSOM requires at least one mapping")
    prefixes = metadata.get("curie_map", {})
    for definition in metadata.get("extension_definitions", []):
        for key in ("property", "type_hint"):
            value = definition.get(key, "")
            if not value or value.partition(":")[0] not in prefixes:
                raise ValueError(f"SSSOM/TSV extension {key} must be a declared CURIE")
            _expand(value, prefixes)
    for position, row in enumerate(rows, 1):
        if None in row or any(value is None for value in row.values()):
            raise ValueError(f"Malformed profiled SSSOM row {position}")
        if validate_scope_row(row, metadata) is None:
            raise ValueError(f"Required scope profile lost at row {position}")
        for field in required:
            if not row.get(field):
                raise ValueError(f"Missing {field} at row {position}")
            if row[field].partition(":")[0] not in prefixes:
                raise ValueError(f"SSSOM/TSV {field} must be a declared CURIE")
            _expand(row[field], prefixes)
        for definition in metadata["extension_definitions"]:
            if definition["type_hint"] == "linkml:Uriorcurie":
                value = row.get(definition["slot_name"], "")
                if value and value.partition(":")[0] not in prefixes:
                    raise ValueError(
                        f"SSSOM/TSV {definition['slot_name']} must be a declared CURIE"
                    )


def read_profile_table(content: bytes) -> tuple[dict, list[str], list[dict]]:
    """Read a required-profile TSV without losing extensions or accepting legacy fallback."""
    stream = io.StringIO(content.decode("utf-8"))
    header = []
    for line in stream:
        if not line.startswith("#"):
            first = line
            break
        header.append(line[1:].removeprefix(" "))
    else:
        raise ValueError("Missing SSSOM table")
    metadata = _load_yaml("".join(header))
    reader = csv.DictReader(io.StringIO(first + stream.read()), delimiter="\t", strict=True)
    fields = list(reader.fieldnames or [])
    rows = list(reader)
    _validate_profile_table(metadata, fields, rows)
    return metadata, fields, rows


def write_profile_table(metadata: dict, fields: list[str], rows: list[dict]) -> bytes:
    """Serialize declared profile extensions deterministically as standard SSSOM/TSV."""
    metadata, rows = deepcopy(metadata), deepcopy(rows)
    prefixes = metadata.get("curie_map", {})
    curie_fields = {"subject_id", "predicate_id", "object_id", "mapping_justification"}
    for definition in metadata.get("extension_definitions", []):
        for key in ("property", "type_hint"):
            definition[key] = _compact(definition[key], prefixes)
        if definition["type_hint"] == "linkml:Uriorcurie":
            field = definition["slot_name"]
            curie_fields.add(field)
            if metadata.get(field):
                metadata[field] = _compact(metadata[field], prefixes)
    for row in rows:
        for field in curie_fields:
            if row.get(field):
                row[field] = _compact(row[field], prefixes)
    _validate_profile_table(metadata, fields, rows)
    stream = io.StringIO(newline="")
    for line in yaml.safe_dump(metadata, sort_keys=False, allow_unicode=True).splitlines():
        stream.write(f"# {line}\n")
    writer = csv.DictWriter(stream, fieldnames=fields, delimiter="\t", lineterminator="\n")
    writer.writeheader()
    writer.writerows(rows)
    return stream.getvalue().encode("utf-8")

"""Complete-payload and owning-record evidence checks shared by reviewed exports."""

from __future__ import annotations

import hashlib
import json


def payload_sha256(payload: dict) -> str:
    """Hash the entire reviewed payload, including structured source qualifiers."""
    return hashlib.sha256(
        json.dumps(
            payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
        ).encode()
    ).hexdigest()


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"Duplicate JSON key: {key}")
        result[key] = value
    return result


def _proof(content: bytes, name: str) -> dict:
    result = json.loads(content, object_pairs_hook=_unique_object)
    if not isinstance(result, dict):
        raise ValueError(f"Expected JSON object: {name}")
    return result


def validate_review_decision(
    decision: dict,
    payload: dict,
    owner: str,
    owner_sha256: str,
    verified: dict[str, bytes],
    proofs: dict,
    *,
    require_owner_path: bool = False,
) -> None:
    """Verify a complete claim against the existing owner/evidence review format.

    Callers independently resolve the owning record and verify every input's
    digest before supplying its bytes. This verifier is shared by mapping and
    companion-claim exports; a checksum or receipt alone confers no approval.
    """
    if (
        decision.get("row_sha256") != payload_sha256(payload)
        or decision.get("owner_record") != owner
    ):
        raise ValueError("Review row payload or owner does not match source")
    if decision.get("disposition") not in {"SUPPORTED", "WITHHOLD"}:
        raise ValueError("Invalid scientific disposition")
    if not isinstance(decision.get("review_reason"), str) or not decision["review_reason"].strip():
        raise ValueError("Missing scientific review reason")
    evidence, key = decision.get("review_evidence"), decision.get("evidence_key")
    if evidence not in verified or not isinstance(key, str) or not key.strip():
        raise ValueError("Missing hash-bound evidence reference")
    if evidence not in proofs:
        proofs[evidence] = _proof(verified[evidence], evidence)
    entry = proofs[evidence].get("entries", {}).get(key)
    expected = {field: decision[field] for field in ("row_sha256", "disposition", "review_reason")}
    expected["owner_record_sha256"] = owner_sha256
    if require_owner_path:
        expected["owner_record"] = owner
    if not isinstance(entry, dict) or any(
        entry.get(field) != value for field, value in expected.items()
    ):
        raise ValueError("Scientific decision disagrees with exact evidence entry")

